/**
 * Helpers for writing the user's $member entity + entity_identities rows.
 *
 * Used by the signup hook to populate the identity graph so the gateway can
 * later route inbound messages back to the right user's personal org via a
 * single entity_identities lookup.
 */

import { normalizeSlackUserId, SLACK_IDENTITY } from "@lobu/connectors/slack-identity";
import { fetchUserInfoWithRaw } from "../connect/oauth-providers";
import { getDb } from "../db/client";
import {
	type ResolvedTenantMember,
	resolveMemberOrgsForUser,
} from "../identity/auth-hook";
import logger from "../utils/logger";
import {
	ensureMemberEntity,
	resolveMemberSchemaFields,
} from "../utils/member-entity";
import { getEnabledLoginProviderConfigs } from "./config";

const log = logger.child({ module: "auth-subject-identities" });

interface PersonalSubject {
	userId: string;
	email: string;
	name?: string | null;
	image?: string | null;
	/**
	 * Role recorded on a NEWLY created `$member` (ignored when the entity already
	 * exists — ensureMemberEntity never rewrites the role of an existing member).
	 * Defaults to `owner` for the personal-org sign-up path; the backfill passes
	 * the member row's actual role so a drifted non-owner is not minted as owner.
	 */
	role?: string;
}

interface IdentityRow {
	namespace: string;
	identifier: string;
}

type Sql = ReturnType<typeof getDb>;

/**
 * Insert (or no-op on conflict) entity_identities rows pointing at the given
 * member entity. The unique index on (organization_id, namespace, identifier)
 * WHERE deleted_at IS NULL guards against duplicates.
 */
async function writeIdentities(
	sql: Sql,
	organizationId: string,
	memberEntityId: number,
	source: string,
	rows: IdentityRow[],
): Promise<void> {
	for (const row of rows) {
		await sql`
      INSERT INTO entity_identities (
        organization_id, entity_id, namespace, identifier, source_connector
      ) VALUES (
        ${organizationId}, ${memberEntityId}, ${row.namespace}, ${row.identifier}, ${source}
      )
      ON CONFLICT (organization_id, namespace, identifier) WHERE deleted_at IS NULL
      DO NOTHING
    `;
	}
}

/**
 * Point a workspace-scoped chat identity at the user's `$member`, taking it over
 * from a `person` entity when one already owns it.
 *
 * Why an UPDATE and not another INSERT: `entity_identities` has a live-unique
 * index on `(organization_id, namespace, identifier)`, so the claim exists at
 * most once. `writeIdentities`' `ON CONFLICT DO NOTHING` therefore SILENTLY LOSES
 * whenever the ACL sync minted a `person` for this workspace user before the
 * human ever signed in — which is the normal ordering, since channel sync runs
 * on a timer and sign-in is a one-off. The gate only ever resolves a `$member`
 * (channel-visibility.ts), so leaving the claim on the `person` hides every
 * enforced channel from its real owner.
 *
 * Re-pointing the claim is sufficient on its own: the ACL graph builder resolves
 * members by whoever owns the identity (`resolveMembers` is deliberately
 * type-agnostic) and reconciles `member_of` edges from that entity on the next
 * sync tick, so the edges follow the claim. Writing edges here by hand would be
 * undone by that same reconcile.
 *
 * SAFETY: only ever called with an identity proven by the provider's own OIDC
 * token for THIS user, and only for an org the user is already a better-auth
 * member of. It never grants org membership, and it never matches on a
 * user-editable field such as a Slack profile email — a workspace admin can set
 * those, which would let an attacker attach their `U…` to a victim's `$member`.
 *
 * The takeover is scoped to `person` entities. A claim already held by another
 * `$member` is a genuine identity conflict (two humans, one Slack id) and is
 * left alone — fail closed, never steal.
 */
async function adoptSlackIdentityOntoMember(
	sql: Sql,
	organizationId: string,
	memberEntityId: number,
	identifier: string,
): Promise<"created" | "adopted" | "already-owned" | "conflict"> {
	const inserted = await sql<{ id: number }>`
    INSERT INTO entity_identities (
      organization_id, entity_id, namespace, identifier, source_connector
    ) VALUES (
      ${organizationId}, ${memberEntityId}, ${SLACK_IDENTITY.USER_ID}, ${identifier}, 'auth:signup'
    )
    ON CONFLICT (organization_id, namespace, identifier) WHERE deleted_at IS NULL
    DO NOTHING
    RETURNING id
  `;
	if (inserted.length > 0) return "created";

	// Take over only from a `person`; a `$member` holder means two humans claim
	// one workspace id, which must not be silently reassigned.
	const adopted = await sql<{ id: number }>`
    UPDATE entity_identities ei
    SET entity_id = ${memberEntityId},
        source_connector = 'auth:signup',
        -- Keep a trail back to the person we took this from, matching the
        -- convention in entity-merge.ts (COALESCE so a re-run never overwrites
        -- the ORIGINAL owner with an intermediate one).
        merged_from_entity_id = COALESCE(ei.merged_from_entity_id, ei.entity_id),
        updated_at = current_timestamp
    FROM entities e
    JOIN entity_types et
      ON et.id = e.entity_type_id
     AND et.organization_id = e.organization_id
    WHERE ei.organization_id = ${organizationId}
      AND ei.namespace = ${SLACK_IDENTITY.USER_ID}
      AND ei.identifier = ${identifier}
      AND ei.deleted_at IS NULL
      AND e.id = ei.entity_id
      AND e.organization_id = ei.organization_id
      AND et.slug = 'person'
    RETURNING ei.id
  `;
	if (adopted.length > 0) return "adopted";

	const mine = await sql<{ id: number }>`
    SELECT id FROM entity_identities
    WHERE organization_id = ${organizationId}
      AND namespace = ${SLACK_IDENTITY.USER_ID}
      AND identifier = ${identifier}
      AND entity_id = ${memberEntityId}
      AND deleted_at IS NULL
    LIMIT 1
  `;
	return mine.length > 0 ? "already-owned" : "conflict";
}

async function findMemberEntityIdByEmail(
	sql: Sql,
	organizationId: string,
	email: string,
): Promise<number | null> {
	const { emailField } = await resolveMemberSchemaFields(organizationId);
	const rows = await sql.unsafe(
		`SELECT e.id
    FROM entities e
    JOIN entity_types et ON et.id = e.entity_type_id
    WHERE et.slug = '$member'
      AND e.organization_id = $1
      AND e.metadata->>$2 = $3
      AND e.deleted_at IS NULL
    LIMIT 1`,
		[organizationId, emailField, email],
	);
	if (rows.length === 0) return null;
	return Number(rows[0].id);
}

/**
 * Create a $member entity for the user in the given org and write the core
 * personal identifiers (auth_user_id, email). Idempotent — safe to call again.
 */
export async function provisionMemberAndCoreIdentities(
	organizationId: string,
	subject: PersonalSubject,
): Promise<{ memberEntityId: number }> {
	const sql = getDb();
	const owners = await sql<{ email: string | null }>`
    SELECT email FROM "user" WHERE id = ${subject.userId} LIMIT 1
  `;
	if (
		owners[0]?.email?.trim().toLowerCase() !==
		subject.email.trim().toLowerCase()
	) {
		throw new Error(
			`Refusing to provision identities for user ${subject.userId}: user does not own the member email`,
		);
	}

	await ensureMemberEntity({
		organizationId,
		userId: subject.userId,
		name: subject.name?.trim() || subject.email.split("@")[0],
		email: subject.email,
		image: subject.image ?? undefined,
		role: subject.role ?? "owner",
		status: "active",
	});

	const memberEntityId = await findMemberEntityIdByEmail(
		sql,
		organizationId,
		subject.email,
	);
	if (memberEntityId === null) {
		throw new Error(
			`Failed to locate $member entity for user ${subject.userId} in org ${organizationId} after ensureMemberEntity`,
		);
	}

	await writeIdentities(sql, organizationId, memberEntityId, "auth:signup", [
		{ namespace: "auth_user_id", identifier: subject.userId },
		{ namespace: "email", identifier: subject.email.toLowerCase() },
	]);

	return { memberEntityId };
}

/**
 * The slice of a BetterAuth social-login account this needs. Structurally
 * satisfied by the `accountSummary` the auth hooks already build.
 */
export interface LoginAccountForSlackIdentity {
	providerId: string;
	userId: string;
	accessToken?: string | null;
	/**
	 * The provider's external account id (the bare Slack `U…` sub), distinct
	 * from the BetterAuth row PK. Preferred over the userinfo body when present.
	 */
	accountId?: string | null;
	/**
	 * The OIDC id_token BetterAuth stored on the account row at the login code
	 * exchange. Slack's id_token payload carries both `https://slack.com/team_id`
	 * and `https://slack.com/user_id`, so when present we read them straight from
	 * it — no second HTTP round-trip / provider-config lookup needed.
	 */
	idToken?: string | null;
}

/**
 * Decode the claims (payload) of a JWT without verifying its signature. Safe
 * here because this is our own server-stored token from a TLS code exchange —
 * same trust level as the access token we already store and use. Mirrors
 * better-auth's own `decodeJwt`. Returns null on any malformation.
 */
export function decodeJwtClaims(jwt: string): Record<string, unknown> | null {
	const seg = jwt.split(".")[1];
	if (!seg) return null;
	try {
		return JSON.parse(Buffer.from(seg, "base64url").toString("utf8")) as Record<
			string,
			unknown
		>;
	} catch {
		return null;
	}
}

/**
 * Injected boundary so tests can stub the network reads (userinfo fetch +
 * provider config) while exercising the real DB write path. Defaults wire the
 * production implementations. This is the `isolate: false` vitest-safe seam:
 * the integration suite shares one module graph, so `vi.mock` of these shared
 * singletons is unreliable — dependency injection is the durable alternative.
 */
export interface PersistLoginSlackIdentityDeps {
	/**
	 * EVERY org where this user is a `$member`, not just their personal one — a
	 * Slack workspace identity is meaningful in each org whose ACL graph covers
	 * that workspace, and the authz gate resolves per-org.
	 */
	resolveMemberOrgsForUser: (
		userId: string,
	) => Promise<ResolvedTenantMember[]>;
	getEnabledLoginProviderConfigs: typeof getEnabledLoginProviderConfigs;
	fetchUserInfoWithRaw: typeof fetchUserInfoWithRaw;
}

const defaultPersistDeps: PersistLoginSlackIdentityDeps = {
	resolveMemberOrgsForUser,
	getEnabledLoginProviderConfigs,
	fetchUserInfoWithRaw,
};

/**
 * On Slack sign-in, write the user's team-scoped `slack_user_id` (`T…:U…`) onto
 * their `$member` entity, sourced `auth:signup`, in EVERY org where they are a
 * member. Idempotent.
 *
 * Effect: the ACL Slack channel-graph collapses the workspace member onto the
 * existing `$member` instead of forking a separate `person`, because both sides
 * now resolve on the same canonical `slack_user_id`.
 *
 * Runs across every member org, not just the personal one: a workspace is
 * commonly connected to a SHARED org, and the authz gate resolves per-org — so
 * writing only to the personal org leaves the user invisible in exactly the org
 * whose channels they are trying to read.
 *
 * Fire-and-forget — failures log and never throw into the auth hook.
 */
export async function persistLoginSlackIdentity(
	account: LoginAccountForSlackIdentity,
	deps: PersistLoginSlackIdentityDeps = defaultPersistDeps,
): Promise<void> {
	try {
		if (account.providerId.trim().toLowerCase() !== "slack") return;
		if (!account.accessToken) return;

		const memberOrgs = await deps.resolveMemberOrgsForUser(account.userId);
		if (memberOrgs.length === 0) {
			log.debug(
				{ userId: account.userId },
				"slack-identity: no tenant $member yet — skipping slack_user_id write",
			);
			return;
		}

		let teamId: string | null | undefined;
		let bareUser: string | null | undefined;
		let source: "id_token" | "userinfo-fallback" = "id_token";

		// PRIMARY: read team + user straight out of the stored id_token. No network.
		if (account.idToken) {
			const claims = decodeJwtClaims(account.idToken);
			if (claims) {
				teamId = claims["https://slack.com/team_id"] as
					| string
					| null
					| undefined;
				bareUser = (account.accountId ??
					claims["https://slack.com/user_id"] ??
					claims.sub) as string | null | undefined;
			}
		}

		// FALLBACK: no id_token (or it yielded no team_id) → the userinfo endpoint.
		// One extra HTTP round-trip + a provider-config DB read, kept behind the
		// injected deps seam so it stays testable.
		if (!teamId) {
			source = "userinfo-fallback";
			// Resolve the Slack userinfo endpoint from the BASELINE catalog config
			// only (org id = null). We are about to send the user's real Slack OAuth
			// access token to `userinfoUrl`, so that URL must come from a trusted
			// source. An org-specific provider definition SHADOWS the baseline
			// (mergeLoginProviderConfigs), so reading it from any org the user
			// belongs to would let a tenant-controlled `userinfoUrl` receive the
			// token — an exfiltration vector, and unrelated to whichever org
			// actually initiated the OAuth exchange. The endpoint is a fixed
			// provider property, identical for every tenant, so the baseline is
			// both correct and safe.
			const cfgs = await deps.getEnabledLoginProviderConfigs(null);
			const slackCfg = cfgs.find((c) => c.provider.toLowerCase() === "slack");
			const { raw } = await deps.fetchUserInfoWithRaw({
				provider: "slack",
				accessToken: account.accessToken,
				userinfoUrl: slackCfg?.userinfoUrl,
			});
			teamId = raw?.["https://slack.com/team_id"] as string | null | undefined;
			bareUser = (account.accountId ??
				raw?.["https://slack.com/user_id"] ??
				raw?.sub) as string | null | undefined;
		}

		// null = missing team id or malformed → NEVER write a bare, un-scoped id
		// (two workspaces can share a `U…`, so a bare id would bleed across orgs).
		const combined = normalizeSlackUserId(teamId, bareUser);
		if (!combined) {
			log.debug(
				{ userId: account.userId },
				"slack-identity: missing team_id or user id — skipping slack_user_id write",
			);
			return;
		}

		const sql = getDb();
		for (const org of memberOrgs) {
			const outcome = await adoptSlackIdentityOntoMember(
				sql,
				org.tenantOrganizationId,
				org.memberEntityId,
				combined,
			);
			if (outcome === "conflict") {
				// Another `$member` in this org already holds this Slack id. Two
				// humans cannot share one workspace account, so this is a data
				// problem a person must look at — never silently reassign.
				log.warn(
					{
						userId: account.userId,
						organizationId: org.tenantOrganizationId,
						memberEntityId: org.memberEntityId,
					},
					"slack-identity: slack_user_id already claimed by a different $member — leaving it alone",
				);
				continue;
			}
			log.debug(
				{
					userId: account.userId,
					organizationId: org.tenantOrganizationId,
					source,
					outcome,
				},
				"slack-identity: linked slack_user_id to $member",
			);
		}
	} catch (err) {
		log.error(
			{ err, userId: account.userId, providerId: account.providerId },
			"slack-identity: failed to persist slack_user_id on login",
		);
	}
}

/**
 * The generic access-graph engine — ONE materializer behind every ACL source.
 *
 * A "source" (a Slack workspace, a GitHub org, later Jira/Drive/…) reduces to the
 * same shape: a set of RESOURCES (channels, repos, projects), each with an
 * AUDIENCE of MEMBERS who may read it. This engine takes that normalized shape
 * and writes it into the existing entity graph — exactly the way the original
 * `buildSlackChannelGraph` did, but with the resource/member specifics lifted
 * into parameters so a second source reuses the whole body instead of copying it.
 *
 * It owns everything that was identical (or should have been) between the Slack
 * channel graph and the GitHub team graph:
 *   - resolve an org owner/admin to attribute entities/edges to (`created_by`);
 *   - find-or-create the resource entity TYPE and the `member_of` relationship
 *     type (reuse, no migration);
 *   - resolve each resource to its entity, keyed on a source-specific identity
 *     namespace (`slack_channel_id`, `github_repo_id`, …);
 *   - resolve each member IDENTITY-FIRST and TYPE-AGNOSTICALLY — a member who has
 *     already signed in owns their identity claim on a `$member` entity, so we
 *     collapse onto THAT entity rather than forking a duplicate `person` (the
 *     correctness fix the Slack builder had and the original GitHub builder did
 *     NOT — folding GitHub onto this engine fixes it for free);
 *   - write `member_of` (member → resource) edges idempotently;
 *   - RECONCILE departures (soft-delete edges to a synced resource whose member is
 *     no longer present) so leavers lose access on the next sync;
 *   - stamp `authz_source_acl_state` ('full','fresh') so the gate begins enforcing
 *     the connection.
 *
 * Tenant-scoped, idempotent, best-effort: everything filters on `organizationId`;
 * edges dedupe on the live-triple unique index; nothing here throws on a
 * data-shaped problem (the CALLER's fetch layer owns fail-closed-on-error).
 */

import { createLogger } from '@lobu/core';
import {
  ACL_RESOURCE_TYPE_SLUG,
  type AccessIdentitySpec,
  type AccessMember,
  type AccessResource,
} from '@lobu/connector-sdk';
import { getDb, pgBigintArray, pgTextArray } from '../db/client.js';
import { runtimeConnectionIdToSlug } from '../lobu/stores/connections-projection.js';
import { resolveEventAttributionsForItems } from '../utils/entity-link-upsert.js';
import { ensureResourceEntityType } from './acl-resource-type.js';

const logger = createLogger('access-graph');

const MEMBER_OF_TYPE_SLUG = 'member_of';

export type { AccessIdentitySpec, AccessMember, AccessResource };
export { ensureResourceEntityType } from './acl-resource-type.js';

export interface AccessGraphResult {
  /** Resource key → the entity id that now represents it. */
  resourceEntityIds: Record<string, number>;
  /** Distinct member entity ids that gained a `member_of` edge. */
  memberEntityIds: number[];
  createdEdges: number;
  removedEdges: number;
}

const EMPTY_RESULT: AccessGraphResult = {
  resourceEntityIds: {},
  memberEntityIds: [],
  createdEdges: 0,
  removedEdges: 0,
};

/** Resolve an org owner/admin as `entities.created_by` / edge `created_by`
 * (NOT NULL). Same query both source builders used. */
async function resolveOrgCreator(orgId: string): Promise<string | null> {
  const sql = getDb();
  const rows = await sql<{ userId: string }>`
		SELECT "userId"
		FROM "member"
		WHERE "organizationId" = ${orgId}
		ORDER BY CASE role WHEN 'owner' THEN 0 WHEN 'admin' THEN 1 ELSE 2 END,
		         "createdAt" ASC
		LIMIT 1
	`;
  return rows.length > 0 ? rows[0].userId : null;
}

/** Ensure the org has a `person` entity type — the type new (genuinely-unknown)
 * members are auto-created as. Prod seeds default types at org creation, but a
 * brand-new/default org may not have it yet; without it those members would
 * silently fail to resolve while the connection is still stamped enforced (their
 * recall would then fail closed). */
async function ensurePersonEntityType(orgId: string): Promise<void> {
  const sql = getDb();
  await sql`
		INSERT INTO entity_types (slug, name, organization_id, created_at, updated_at)
		VALUES ('person', 'Person', ${orgId}, current_timestamp, current_timestamp)
		ON CONFLICT (organization_id, slug) WHERE organization_id IS NOT NULL AND deleted_at IS NULL
		DO NOTHING
	`;
}

/** Find-or-create the org-scoped `member_of` relationship type. */
async function ensureMemberOfType(orgId: string): Promise<number> {
  const sql = getDb();
  const rows = await sql`
		INSERT INTO entity_relationship_types
			(slug, name, description, organization_id, is_symmetric, created_by, created_at, updated_at)
		VALUES
			(${MEMBER_OF_TYPE_SLUG}, 'Member of', 'A member belongs to an ACL resource (channel, repo, …)', ${orgId},
			 false, NULL, current_timestamp, current_timestamp)
		ON CONFLICT (organization_id, slug) WHERE status = 'active'
		DO UPDATE SET updated_at = EXCLUDED.updated_at
		RETURNING id
	`;
  return Number(rows[0].id);
}

/** Stamp the connection's ACL state so the gate begins enforcing it. */
async function markAclEnforced(orgId: string, connectionId: string): Promise<void> {
  const sql = getDb();
  await sql`
		INSERT INTO authz_source_acl_state
			(organization_id, connection_id, acl_support, freshness_state, last_synced_at, created_at, updated_at)
		VALUES (${orgId}, ${connectionId}, 'full', 'fresh', current_timestamp, current_timestamp, current_timestamp)
		ON CONFLICT (organization_id, connection_id)
		DO UPDATE SET acl_support = 'full', freshness_state = 'fresh',
		              last_synced_at = current_timestamp, updated_at = current_timestamp
	`;
}

/**
 * Resolve every distinct member to an entity id, IDENTITY-FIRST and
 * TYPE-AGNOSTIC: a member collapses onto any existing entity (`$member`,
 * `person`, …) carrying ANY of their identities; only genuinely-new members get
 * a freshly-created `person`. Returns a map member.key → entity id.
 */
async function resolveMembers(
  orgId: string,
  connectorKey: string,
  connectionId: number | null,
  members: AccessMember[],
  memberIdentities: AccessIdentitySpec[],
): Promise<Map<string, number>> {
  const byKey = new Map<string, number>();
  if (members.length === 0) return byKey;

  // Gather identity values per namespace and look up existing owners (any type).
  const valuesByNamespace = new Map<string, Set<string>>();
  for (const m of members) {
    for (const id of m.identities) {
      if (!id.value) continue;
      const set = valuesByNamespace.get(id.namespace) ?? new Set<string>();
      set.add(id.value);
      valuesByNamespace.set(id.namespace, set);
    }
  }
  const existing = new Map<string, number>(); // `${namespace}|${value}` → entity id
  const sql = getDb();
  for (const [namespace, values] of valuesByNamespace) {
    const list = [...values];
    if (list.length === 0) continue;
    const rows = await sql<{ identifier: string; entity_id: number }>`
			SELECT identifier, entity_id
			FROM entity_identities
			WHERE organization_id = ${orgId}
			  AND namespace = ${namespace}
			  AND identifier = ANY(${pgTextArray(list)}::text[])
			  AND deleted_at IS NULL
		`;
    for (const r of rows) {
      existing.set(`${namespace}|${String(r.identifier)}`, Number(r.entity_id));
    }
  }

  const toCreate: AccessMember[] = [];
  for (const m of members) {
    let hit: number | undefined;
    for (const id of m.identities) {
      const found = existing.get(`${id.namespace}|${id.value}`);
      if (found !== undefined) {
        hit = found;
        break;
      }
    }
    if (hit !== undefined) byKey.set(m.key, hit);
    else toCreate.push(m);
  }

  if (toCreate.length === 0) return byKey;

  // Auto-create a `person` for each genuinely-new member, carrying ALL their
  // declared identities so a later source (or login) collapses onto them.
  const items = toCreate.map((m) => {
    const metadata: Record<string, unknown> = { display_name: m.name ?? m.key };
    for (const id of m.identities) metadata[id.namespace] = id.value;
    return { origin_type: 'access_member', metadata };
  });
  const resolved = await resolveEventAttributionsForItems({
    connectorKey,
    connectionId,
    orgId,
    items,
    rules: {
      access_member: [
        {
          role: 'authored_by',
          entityType: 'person',
          autoCreate: true,
          titlePath: 'metadata.display_name',
          identities: memberIdentities.map((spec) => ({
            namespace: spec.namespace,
            eventPath: `metadata.${spec.namespace}`,
            primary: spec.primary,
          })),
        },
      ],
    },
  });
  for (let i = 0; i < toCreate.length; i++) {
    const ids = resolved.get(i);
    if (ids && ids.length > 0) byKey.set(toCreate[i].key, ids[0]);
  }
  return byKey;
}

/**
 * Materialize a source's resource→audience graph and mark the connection
 * ACL-enforced. The CALLER normalizes its raw API shape into `resources`
 * (Slack channels with `T:C`/`T:U` keys, GitHub repos with collaborators, …);
 * this body is source-agnostic.
 */
export async function buildAccessGraph(params: {
  organizationId: string;
  connectionId: string;
  connectorKey: string;
  /** Identity namespace for resource keys (e.g. `slack_channel_id`). */
  resourceNamespace: string;
  memberIdentities: AccessIdentitySpec[];
  resources: AccessResource[];
}): Promise<AccessGraphResult> {
  const { organizationId, connectionId, connectorKey, resourceNamespace, memberIdentities } =
    params;
  const resources = params.resources.filter((r) => r.key);
  if (resources.length === 0) return EMPTY_RESULT;

  const creatorUserId = await resolveOrgCreator(organizationId);
  if (!creatorUserId) {
    logger.warn(
      { organization_id: organizationId, connector: connectorKey },
      'Access graph skipped: org has no member to attribute as entity creator',
    );
    return EMPTY_RESULT;
  }

  await ensureResourceEntityType(organizationId);
  await ensurePersonEntityType(organizationId);

  // ACL state uses a runtime connection id, while identity provenance references
  // the stored numeric row. Resolve by slug (chat connections) or id text (data
  // connectors) without assuming the runtime id itself is numeric.
  const [storedConnection] = await getDb()<{ id: number }>`
    SELECT id
    FROM connections
    WHERE organization_id = ${organizationId}
      AND connector_key = ${connectorKey}
      AND deleted_at IS NULL
      AND (
        slug = ${runtimeConnectionIdToSlug(connectionId)}
        OR id::text = ${connectionId}
      )
    LIMIT 1
  `;
  const identityConnectionId = storedConnection
    ? Number(storedConnection.id)
    : null;

  // 1) Resolve every resource to its entity, keyed on the source identity namespace.
  const resourceItems = resources.map((r) => ({
    origin_type: 'access_resource',
    metadata: { resource_key: r.key, resource_name: r.name ?? r.key },
  }));
  const resolvedResources = await resolveEventAttributionsForItems({
    connectorKey,
    connectionId: identityConnectionId,
    orgId: organizationId,
    items: resourceItems,
    rules: {
      access_resource: [
        {
          role: 'belongs_to',
          entityType: ACL_RESOURCE_TYPE_SLUG,
          autoCreate: true,
          titlePath: 'metadata.resource_name',
          identities: [
            {
              namespace: resourceNamespace,
              eventPath: 'metadata.resource_key',
              primary: true,
            },
          ],
        },
      ],
    },
  });
  const resourceEntityIds: Record<string, number> = {};
  const resourceEntityIdByIndex = new Map<number, number>();
  for (let i = 0; i < resources.length; i++) {
    const ids = resolvedResources.get(i);
    if (ids && ids.length > 0) {
      resourceEntityIds[resources[i].key] = ids[0];
      resourceEntityIdByIndex.set(i, ids[0]);
    }
  }

  // 2) Resolve every DISTINCT member (identity-first, type-agnostic).
  const distinctMembers = new Map<string, AccessMember>();
  for (const r of resources) {
    for (const m of r.members) {
      if (m.key && !distinctMembers.has(m.key)) distinctMembers.set(m.key, m);
    }
  }
  const memberEntityByKey = await resolveMembers(
    organizationId,
    connectorKey,
    identityConnectionId,
    [...distinctMembers.values()],
    memberIdentities,
  );

  // 3) Write member → resource `member_of` edges, idempotent on the live-triple
  // unique index. Accumulate the CURRENT member set per resource for reconcile.
  const typeId = await ensureMemberOfType(organizationId);
  const sql = getDb();

  // Keep each resource entity's display name fresh. `titlePath` only sets the
  // name on auto-CREATE, so a name that wasn't available at first graph (or a
  // later channel/repo RENAME) would otherwise stick to the stale value / the
  // raw id. Refresh from the source-provided name here. Scoped to the resources
  // in this build; idempotent (the `name <>` guard no-ops when unchanged).
  for (let i = 0; i < resources.length; i++) {
    const id = resourceEntityIdByIndex.get(i);
    const name = resources[i].name;
    if (id && name) {
      await sql`
        UPDATE entities
        SET name = ${name}, updated_at = current_timestamp
        WHERE id = ${id}
          AND organization_id = ${organizationId}
          AND name <> ${name}
          AND deleted_at IS NULL
      `;
    }
  }

  const memberEntityIds = new Set<number>();
  const currentMembersByResource = new Map<number, Set<number>>();
  let createdEdges = 0;
  for (let i = 0; i < resources.length; i++) {
    const resourceEntityId = resourceEntityIdByIndex.get(i);
    if (resourceEntityId === undefined) continue;
    const resourceMembers = currentMembersByResource.get(resourceEntityId) ?? new Set<number>();
    currentMembersByResource.set(resourceEntityId, resourceMembers);
    for (const m of resources[i].members) {
      const memberEntityId = memberEntityByKey.get(m.key);
      if (memberEntityId === undefined) continue;
      memberEntityIds.add(memberEntityId);
      resourceMembers.add(memberEntityId);
      const inserted = await sql<{ id: number }[]>`
				INSERT INTO entity_relationships (
					organization_id, from_entity_id, to_entity_id, relationship_type_id,
					confidence, source, created_by, updated_by, created_at, updated_at
				) VALUES (
					${organizationId}, ${memberEntityId}, ${resourceEntityId}, ${typeId},
					1.0, 'feed', ${creatorUserId}, ${creatorUserId},
					current_timestamp, current_timestamp
				)
				ON CONFLICT (from_entity_id, to_entity_id, relationship_type_id)
					WHERE deleted_at IS NULL
				DO NOTHING
				RETURNING id
			`;
      if (inserted.length > 0) createdEdges += 1;
    }
  }

  // 4) Reconcile DEPARTURES — the build is a full re-sync of each resource's
  // membership, so a `member_of` edge to a synced resource whose member is NOT
  // in the current set means that person left: soft-delete it so they lose
  // access immediately. Scoped to `to_entity_id` = a resource we just synced, so
  // edges to OTHER resource types (a different source's graph) are never touched.
  // An empty member set deletes all of that resource's edges — the caller must
  // not pass empty-on-fetch-error.
  let removedEdges = 0;
  for (const [resourceEntityId, resourceMembers] of currentMembersByResource) {
    const keep = [...resourceMembers];
    const removed = await sql<{ id: number }[]>`
			UPDATE entity_relationships
			SET deleted_at = current_timestamp, updated_at = current_timestamp
			WHERE organization_id = ${organizationId}
			  AND relationship_type_id = ${typeId}
			  AND to_entity_id = ${resourceEntityId}
			  AND deleted_at IS NULL
			  AND from_entity_id <> ALL(${pgBigintArray(keep)}::bigint[])
			RETURNING id
		`;
    removedEdges += removed.length;
  }

  await markAclEnforced(organizationId, connectionId);

  logger.info(
    {
      organization_id: organizationId,
      connection_id: connectionId,
      connector: connectorKey,
      resource_type: ACL_RESOURCE_TYPE_SLUG,
      resource_namespace: resourceNamespace,
      resources: Object.keys(resourceEntityIds).length,
      members: memberEntityIds.size,
      created_edges: createdEdges,
      removed_edges: removedEdges,
    },
    'Built access graph',
  );

  return {
    resourceEntityIds,
    memberEntityIds: [...memberEntityIds],
    createdEdges,
    removedEdges,
  };
}

    },
    sql ?? getDb()
  );
}

