/**
 * Sync ONE Slack connection's channel-membership graph. Resolves its captured
 * channels, fetches members per channel, and builds the graph (per team). See
 * the file header for the fail-closed contract.
 */
export async function syncSlackConnectionAcl(
  deps: SlackAclSyncDeps,
  params: { connectionId: string; organizationId: string },
): Promise<SlackAclSyncResult> {
  const { connectionId, organizationId } = params;
  const sql = getDb();

  const bound = await resolveBoundChannelRows(sql, {
    organizationId,
    connectionId,
  });

  // `resolveBoundChannelRows` narrows bindings to THIS connection (by slug), so
  // every row here already belongs to it — we trust connection_id as the scope,
  // NOT a team-string round-trip. `connTeamId` is only used to guard the BYO
  // multi-workspace case: when the connection's tenant id is itself a WORKSPACE
  // (`T…`), a binding for a DIFFERENT workspace is a stray second-connection row
  // and is dropped (fetched with the wrong token → fail-closed otherwise). When
  // the tenant id is NOT a workspace — a Grid ENTERPRISE (`E…`) org-wide install,
  // whose bindings correctly carry the sibling workspace `T…`, or a preview
  // connection (no teamId) — we accept EVERY real-team binding on the connection
  // and group by the binding's own team. Without this relaxation an org-wide
  // install (connTeamId = E…) drops all its `T…` bindings and silently
  // downgrades to the legacy per-agent fence.
  const [conn] = await sql<{ team_id: string | null }>`
		SELECT COALESCE(external_tenant_id, config->'chatMetadata'->>'teamId') AS team_id
		FROM connections
		WHERE slug = ${runtimeConnectionIdToSlug(connectionId)}
		  AND organization_id = ${organizationId}
		  AND credential_mode IS NOT NULL
		  AND deleted_at IS NULL
		LIMIT 1
	`;
  const connTeamId = conn?.team_id ?? null;
  // Is the connection's tenant id itself a concrete workspace? Only then do we
  // enforce workspace equality (BYO foreign-workspace guard). An enterprise `E…`
  // or absent tenant id does NOT constrain the binding team.
  const connScopesWorkspace = /^T[A-Z0-9]+$/i.test(connTeamId ?? '');

  // Only Slack rows that carry a real workspace team can be team-scoped into the
  // graph; a channel with no team id is dropped fail-closed by the gate anyway.
  const slackRows = bound.filter(
    (r) =>
      r.platform.startsWith('slack') &&
      r.team_id &&
      (!connScopesWorkspace || r.team_id === connTeamId),
  );
  if (slackRows.length === 0) {
    return { ok: true, teamsSynced: 0, channelsSynced: 0 };
  }

  // Group channels by workspace/team — one graph build per team.
  const byTeam = new Map<string, string[]>();
  for (const r of slackRows) {
    const channelId = stripPlatformPrefix(r.platform, r.channel_id);
    const list = byTeam.get(r.team_id as string) ?? [];
    list.push(channelId);
    byTeam.set(r.team_id as string, list);
  }

  let teamsSynced = 0;
  let channelsSynced = 0;
  try {
    for (const [teamId, channelIds] of byTeam) {
      const identity = await deps.resolveBotIdentity({ organizationId, teamId, connectionId });
      if (!identity) {
        throw new Error(`No bot token for team ${teamId}`);
      }
      const { token, botUserId } = identity;
      const channels: SlackChannelInput[] = [];
      for (const channelId of channelIds) {
        // Per-channel tolerance for a STALE binding: if the bot was kicked, the
        // channel was archived/deleted, or it's simply not in it, Slack throws
        // `channel_not_found` / `not_in_channel` / `is_archived`. That channel
        // has no readable audience — DROP it from the graph and keep going;
        // fail-closing the whole connection over one dead binding would ungraph
        // every OTHER (readable) channel too. Systemic errors (auth, rate limit)
        // still propagate to the outer catch and fail the connection closed.
        let rawMembers: string[];
        try {
          rawMembers = await deps.slackWeb.conversationMembers(token, channelId);
        } catch (error) {
          const msg = String(error);
          if (
            /channel_not_found|not_in_channel|is_archived|method_not_supported_for_channel_type/.test(
              msg,
            )
          ) {
            // Definitively unreadable (bot kicked / channel archived/gone),
            // NOT transient. Push it with an EMPTY member set so graph
            // reconciliation soft-deletes its stale `member_of` edges (revokes
            // recall) — skipping would leave them alive (fail-OPEN). Transient
            // errors (ratelimit/auth) fall through to `throw` → whole connection
            // fails closed, so we never wipe edges on a flaky fetch.
            logger.warn(
              { organization_id: organizationId, channel_id: channelId, error: msg },
              'Slack conversations.members: channel unreadable (stale binding) — reconciling to no members',
            );
            channels.push({ channelId, memberSlackUserIds: [] });
            continue;
          }
          throw error;
        }
        // The bot is itself a member of every channel it's in, so
        // `conversations.members` includes it. Drop it: a bot is not an audience
        // and must never gain a `member_of` edge (it would inflate "who can
        // recall" AND, via the gate, count as a member). The bot id is the
        // install's, scoped to THIS team. Absent it, we don't filter (no regression).
        const memberSlackUserIds = botUserId
          ? rawMembers.filter((u) => u !== botUserId)
          : rawMembers;
        // Channel name + privacy are BEST-EFFORT display metadata — a failure
        // here must NOT fail-close the whole sync (membership is the contract),
        // so swallow and fall back to the id-as-name in buildSlackChannelGraph.
        let name: string | undefined;
        let isPrivate: boolean | undefined;
        try {
          const info = await deps.slackWeb.conversationInfo(token, channelId);
          name = info.name ?? undefined;
          isPrivate = info.isPrivate;
        } catch (error) {
          logger.warn(
            { organization_id: organizationId, channel_id: channelId, error: String(error) },
            'Slack conversations.info failed — syncing channel without a name',
          );
        }
        channels.push({ channelId, name, isPrivate, memberSlackUserIds });
      }
      await buildAccessGraph({
        organizationId,
        connectionId,
        connectorKey: slackAclSource.key,
        resourceNamespace: slackAclSource.resourceNamespace,
        memberIdentities: slackAclSource.memberIdentities,
        resources: slackChannelsToResources(teamId, channels),
      });
      teamsSynced += 1;
      channelsSynced += channels.length;
    }
    return { ok: true, teamsSynced, channelsSynced };
  } catch (error) {
    logger.error(
      {
        organization_id: organizationId,
        connection_id: connectionId,
        error: String(error),
      },
      'Slack ACL sync failed — marking connection fail-closed',
    );
    await markConnectionAclFailed(organizationId, connectionId);
    return { ok: false, teamsSynced, channelsSynced };
  }
}

/**
 * Resolve the bot token + user id for one Slack connection's ACL sync. Prefers
 * the workspace OAuth app-installation (hosted/managed path); falls back to the
 * connection's OWN bot credentials for a BYO Slack connection that has no
 * install row. Exported so both branches are unit-testable — the BYO fallback
 * is what lets an active-but-BYO connection (real bindings, no install) actually
 * graph instead of failing closed and silently degrading channel memory to org
 * scope.
 */
export async function resolveSlackBotIdentity(
  deps: {
    installStore: ReturnType<CoreServices['getAppInstallationStore']>;
    // Only the read side (`.get`) is used, via resolveSecretValue — accept the
    // minimal SecretStore so callers with either the WritableSecretStore
    // (platform.ts CoreServices) or the SecretStoreRegistry (concrete) type fit.
    secretStore: SecretStore;
    slackWeb: SlackWebApi;
  },
  params: { organizationId: string; teamId: string; connectionId: string },
): Promise<{ token: string; botUserId: string | null } | null> {
  const { installStore, secretStore, slackWeb } = deps;
  const { organizationId, teamId, connectionId } = params;

  // Primary: resolve the install by THIS connection's concrete id
  // (`slackinst-<uuid>` slug = the install external id), NOT by round-tripping
  // the team string. On a Grid ORG-WIDE install the install row is keyed on the
  // ENTERPRISE id, so a per-team `getSlackInstallByTeamId(T…)` lookup misses for
  // every sibling workspace — but the one bot token is enterprise-wide and reads
  // every workspace's channels. Resolving by connection id gives us that token
  // for any `T…` we're graphing. Only slackinst- slugs are installs; a BYO slug
  // (`agentconn-…`) skips straight to the fallback below.
  const connSlug = runtimeConnectionIdToSlug(connectionId);
  const installById = connSlug.startsWith('slackinst-')
    ? await getSlackInstallById(installStore, connSlug)
    : null;
  if (installById && installById.status === 'active') {
    const tokenRef = (installById.config as { botToken?: string }).botToken;
    const token = await orgContext.run(
      { organizationId: installById.organizationId },
      () => resolveSecretValue(secretStore, tokenRef),
    );
    if (token) return { token, botUserId: installById.botUserId ?? null };
  }

  // Secondary: the workspace OAuth app-installation keyed by team (a normal,
  // non-org-wide install whose connection slug may not be the install id).
  const install = await getSlackInstallByTeamId(installStore, teamId);
  if (install && install.status === 'active') {
    const tokenRef = (install.config as { botToken?: string }).botToken;
    const token = await orgContext.run({ organizationId: install.organizationId }, () =>
      resolveSecretValue(secretStore, tokenRef),
    );
    if (token) return { token, botUserId: install.botUserId ?? null };
  }

  // Fallback: a BYO Slack connection has no install row — its bot token + user
  // id live on the connection's own config. The token is a `secret://` ref,
  // resolved under the connection's org exactly like the install path.
  //
  // We fetch by (slug, org) only and check the team OURSELVES rather than in the
  // predicate: a BYO connection created without an OAuth install NEVER persists a
  // teamId (see slack-connection-coordinator: "created without an OAuth install
  // never gets a metadata.teamId"), so a `= ${teamId}` predicate would drop it
  // entirely and the sync would fail closed forever. Instead we self-heal.
  const sql = getDb();
  const [conn] = await sql<{
    organization_id: string;
    // Slack connection config stores botToken at the top level (the
    // OAuth-install writer's shape); COALESCE the chatMetadata nesting too.
    bot_token_ref: string | null;
    bot_user_id: string | null;
    // The team this connection is already known to belong to, if any.
    stored_team_id: string | null;
  }>`
		SELECT organization_id,
		       COALESCE(config->>'botToken', config->'chatMetadata'->>'botToken') AS bot_token_ref,
		       config->'chatMetadata'->>'botUserId' AS bot_user_id,
		       COALESCE(external_tenant_id, config->'chatMetadata'->>'teamId') AS stored_team_id
		FROM connections
		WHERE slug = ${runtimeConnectionIdToSlug(connectionId)}
		  AND organization_id = ${organizationId}
		  AND connector_key = 'slack'
		  AND status = 'active'
		  AND deleted_at IS NULL
		LIMIT 1
	`;
  if (!conn?.bot_token_ref) return null;

  // Guard the FOREIGN-team case: a connection that already carries a DIFFERENT
  // team id must NOT hand back its token for the team we're graphing. Without
  // this, its token would answer channel_not_found for every foreign channel and
  // the empty-member reconcile would wipe live edges the team's REAL connection
  // maintains. A matching stored team is the fast path (no Slack round-trip).
  if (conn.stored_team_id && conn.stored_team_id !== teamId) return null;

  const token = await orgContext.run({ organizationId: conn.organization_id }, () =>
    resolveSecretValue(secretStore, conn.bot_token_ref as string),
  );
  if (!token) return null;

  // Self-heal the teamId-less BYO connection: confirm the token's REAL team from
  // Slack (a stronger guard than a stored string — it verifies the LIVE
  // credential's team), then backfill THAT team onto the row so future ticks take
  // the fast/foreign-team paths above without another auth.test. We backfill the
  // real team even when it isn't the one we were asked to graph: otherwise a
  // connection reached first for a foreign binding would re-hit auth.test every
  // tick forever. Graphing itself still requires the real team to match.
  if (!conn.stored_team_id) {
    let realTeamId: string;
    try {
      ({ teamId: realTeamId } = await slackWeb.authTest(token));
    } catch (error) {
      // A dead/invalid token can't be identified — fail closed for THIS team
      // (leave the connection ungraphed rather than risk wiping a foreign
      // team's edges). Transient failures retry on the next tick.
      logger.warn(
        { connectionId, teamId, error: String(error) },
        'Slack auth.test failed resolving BYO connection team; skipping',
      );
      return null;
    }
    await sql`
			UPDATE connections
			SET external_tenant_id = ${realTeamId}
			WHERE slug = ${runtimeConnectionIdToSlug(connectionId)}
			  AND organization_id = ${organizationId}
			  AND connector_key = 'slack'
			  AND external_tenant_id IS NULL
		`;
    logger.info(
      { connectionId, teamId: realTeamId },
      'Backfilled teamId onto BYO Slack connection from auth.test',
    );
    // Only hand back the token when the confirmed team is the one being graphed;
    // a token for a different workspace must not touch this team's edges.
    if (realTeamId !== teamId) return null;
  }

  return { token, botUserId: conn.bot_user_id };
}

/**
 * The periodic production caller (registered in `scheduled/jobs.ts`). Re-syncs
 * every active Slack connection's channel-membership graph so joins/leaves
 * converge within the tick cadence and the gate's freshness window keeps a
 * stalled connection fail-closed. Runs on one replica per tick (the TaskScheduler
 * runs-queue claim), iterating connections sequentially — membership sync is not
 * latency-critical.
 *
 * Token resolution ({@link resolveSlackBotIdentity}) prefers the workspace OAuth
 * install and falls back to the connection's own BYO bot credentials, so both
 * managed and BYO Slack connections graph. A connection with neither still
 * fails closed via {@link syncSlackConnectionAcl}.
 */
export async function runSlackAclSyncTick(coreServices: CoreServices): Promise<void> {
  const sql = getDb();
  const connRows = await sql<{ slug: string; organization_id: string }>`
		SELECT slug, organization_id
		FROM connections
		WHERE connector_key = 'slack'
		  AND status = 'active'
		  AND credential_mode IS NOT NULL
		  AND deleted_at IS NULL
	`;
  const connections = connRows.map((r) => ({
    id: slugToRuntimeConnectionId(r.slug),
    organization_id: r.organization_id,
  }));
  if (connections.length === 0) return;

  const installStore = coreServices.getAppInstallationStore();
  const secretStore = coreServices.getSecretStore();
  const slackWeb = createSlackWebApi();

  const deps: SlackAclSyncDeps = {
    slackWeb,
    resolveBotIdentity: (params) =>
      resolveSlackBotIdentity({ installStore, secretStore, slackWeb }, params),
  };

  let ok = 0;
  let failed = 0;
  for (const conn of connections) {
    const result = await syncSlackConnectionAcl(deps, {
      connectionId: conn.id,
      organizationId: conn.organization_id,
    });
    if (result.ok) ok += 1;
    else failed += 1;
  }
  logger.info({ connections: connections.length, ok, failed }, 'Slack ACL sync tick complete');
}

/**
 * Bridge between the BetterAuth account hooks and the identity engine.
 *
 * On every social-login `account.create.after` and `account.update.after`,
 * this resolves the user's tenant `$member` and ingests verified facts
 * from the appropriate connector emitter. Fire-and-forget — sign-in must
 * NEVER block on engine work.
 *
 * Provider routing is data: each `providerId` maps to a single emitter
 * here. New providers register a new branch; everything else (rules,
 * matching, derivations) stays generic.
 */

import { getDb } from "../db/client";
import logger from "../utils/logger";
import { connectorCapabilityRegistry } from "./capability-registry";
// Side-effect import: each connector self-registers on load. Add a new
// import here when adding a connector under `./connectors/`.
import "./connectors/google";
import { ingestFacts } from "./engine";

const log = logger.child({ module: "identity-auth-hook" });

interface AuthAccountSummary {
	id: string;
	userId: string;
	providerId: string;
	accessToken?: string | null;
	scope?: string | null;
}

// Connector access-token refreshes (e.g. hourly) fire `account.update.after`
// without a scope change; the userinfo response is keyed on scope, so we
// skip the work when nothing meaningful changed. Bounded by a short TTL so a
// stuck row can't suppress ingest forever, and by a hard size cap so the
// map can't grow without bound under load.
const INGEST_DEDUPE_TTL_MS = 15 * 60 * 1000;
const INGEST_DEDUPE_MAX_ENTRIES = 10_000;
const recentIngest = new Map<string, { scope: string; at: number }>();

function shouldSkipIngest(account: AuthAccountSummary): boolean {
	const prev = recentIngest.get(account.id);
	if (!prev) return false;
	if (Date.now() - prev.at > INGEST_DEDUPE_TTL_MS) {
		recentIngest.delete(account.id);
		return false;
	}
	return prev.scope === (account.scope ?? "");
}

function markIngested(account: AuthAccountSummary): void {
	if (recentIngest.size >= INGEST_DEDUPE_MAX_ENTRIES) {
		// Drop the oldest entry. Map iteration order is insertion order, so the
		// first key is the least-recently-marked account.
		const oldest = recentIngest.keys().next();
		if (!oldest.done) recentIngest.delete(oldest.value);
	}
	recentIngest.set(account.id, { scope: account.scope ?? "", at: Date.now() });
}

export interface ResolvedTenantMember {
	tenantOrganizationId: string;
	memberEntityId: number;
}

/**
 * Find the user's personal org and `$member` entity id. Returns null when
 * personal-org provisioning hasn't yet completed for this user — ingest
 * will be retried on the next account refresh.
 *
 * SINGLE-ORG ON PURPOSE. Callers of this write PERSONAL identity facts (Google
 * profile/contacts and their tombstones) onto the resolved `$member`. Those
 * facts belong in the user's own filing cabinet, so this must never fan out
 * across the shared orgs a user happens to belong to — that would expose one
 * member's personal data to their org-mates. If you need "every org this user
 * is a member of" (e.g. to stamp a workspace-scoped chat identity), use
 * `resolveMemberOrgsForUser` instead; do NOT widen this.
 */
export async function resolveTenantMember(
	userId: string,
): Promise<ResolvedTenantMember | null> {
	const sql = getDb();
	// Restrict to identity rows written by the auth-server signup hook so a
	// user-supplied row can't hijack the lookup, and join on organization_id
	// at every level so a stale cross-org row can't redirect to another tenant.
	const rows = await sql<{ organization_id: string; entity_id: number }>`
    SELECT m."organizationId" AS organization_id, e.id AS entity_id
    FROM "member" m
    JOIN organization o ON o.id = m."organizationId"
    JOIN entity_identities ei
      ON ei.organization_id = m."organizationId"
     AND ei.namespace = 'auth_user_id'
     AND ei.identifier = ${userId}
     AND ei.deleted_at IS NULL
     AND ei.source_connector = 'auth:signup'
    JOIN entities e
      ON e.id = ei.entity_id
     AND e.organization_id = ei.organization_id
     AND e.deleted_at IS NULL
    JOIN entity_types et
      ON et.id = e.entity_type_id
     AND et.organization_id = e.organization_id
     AND et.slug = '$member'
    WHERE m."userId" = ${userId}
      AND o.visibility = 'private'
    -- Prefer the org EXPLICITLY tagged as this user's personal one. Ordering by
    -- createdAt alone is a heuristic that silently picks the oldest private org
    -- the user belongs to — which, once a shared org gains an auth:signup claim,
    -- can be someone else's org, redirecting this user's personal identity facts
    -- into it. The tag is written by personal-org provisioning and by
    -- afterCreateOrganization, so it is the authoritative signal; createdAt stays
    -- only as the tiebreak for users provisioned before the tag existed.
    ORDER BY COALESCE(
               o.metadata::jsonb->>'personal_org_for_user_id' = ${userId},
               false
             ) DESC,
             o."createdAt" ASC
    LIMIT 1
  `;
	if (rows.length === 0) return null;
	return {
		tenantOrganizationId: String(rows[0].organization_id),
		memberEntityId: Number(rows[0].entity_id),
	};
}

/**
 * Every org where this user is a better-auth member AND already has a `$member`
 * entity carrying the trusted `auth:signup` claim.
 *
 * This is the multi-org counterpart to `resolveTenantMember`, for writing a
 * WORKSPACE-SCOPED identity (e.g. Slack's `T…:U…`) onto the user's `$member` in
 * each org that can act on it. Safe to fan out precisely because the value being
 * written is already scoped to the external workspace it came from — unlike the
 * personal identity facts `resolveTenantMember` guards, it carries no data that
 * one org's members shouldn't see.
 *
 * Membership still comes from the better-auth `member` row: this only ever
 * returns orgs the user is genuinely a member of, so it cannot create org
 * membership from connector data.
 */
export async function resolveMemberOrgsForUser(
	userId: string,
): Promise<ResolvedTenantMember[]> {
	const sql = getDb();
	const rows = await sql<{ organization_id: string; entity_id: number }>`
    SELECT m."organizationId" AS organization_id, e.id AS entity_id
    FROM "member" m
    JOIN entity_identities ei
      ON ei.organization_id = m."organizationId"
     AND ei.namespace = 'auth_user_id'
     AND ei.identifier = ${userId}
     AND ei.deleted_at IS NULL
     AND ei.source_connector = 'auth:signup'
    JOIN entities e
      ON e.id = ei.entity_id
     AND e.organization_id = ei.organization_id
     AND e.deleted_at IS NULL
    JOIN entity_types et
      ON et.id = e.entity_type_id
     AND et.organization_id = e.organization_id
     AND et.slug = '$member'
    WHERE m."userId" = ${userId}
    ORDER BY m."organizationId" ASC
  `;
	return rows.map((r) => ({
		tenantOrganizationId: String(r.organization_id),
		memberEntityId: Number(r.entity_id),
	}));
}

/**
 * Schedule the identity-engine ingest for a freshly-created or refreshed
 * social-login account. Fire-and-forget. Errors are logged, not thrown.
 *
 * Provider routing is registry-based — there is no per-provider branch in
 * core code. Each connector self-registers in `connectors/<name>.ts` and
 * the registry maps `providerId` → emitter.
 */
export function scheduleIdentityIngest(account: AuthAccountSummary): void {
	void (async () => {
		try {
			if (!account.accessToken) return;
			if (shouldSkipIngest(account)) {
				log.debug(
					{ accountId: account.id, providerId: account.providerId },
					"identity-engine: scope unchanged within dedupe window; skipping refresh ingest",
				);
				return;
			}
			// BetterAuth can hand back capitalised providerIds depending on the
			// config; the registry stores lower-case keys.
			const providerKey = account.providerId.trim().toLowerCase();
			const emit = connectorCapabilityRegistry.emitter(providerKey);
			if (!emit) {
				log.warn(
					{
						providerId: account.providerId,
						providerKey,
						userId: account.userId,
					},
					"identity-engine: no connector registered for provider; skipping ingest",
				);
				return;
			}
			const emitted = await emit({
				accessToken: account.accessToken,
				sourceAccountId: account.id,
			});
			// emit returning null is the fetch-failure / ambiguous-read signal —
			// calling ingestFacts on null would tombstone every prior fact.
			if (!emitted) return;

			const resolved = await resolveTenantMember(account.userId);
			if (!resolved) {
				log.debug(
					{ userId: account.userId, providerId: account.providerId },
					"identity-engine: no tenant $member yet — skipping ingest",
				);
				return;
			}

			await ingestFacts({
				tenantOrganizationId: resolved.tenantOrganizationId,
				memberEntityId: resolved.memberEntityId,
				userId: account.userId,
				accountIdentity: {
					connectorKey: providerKey,
					providerStableId: emitted.providerStableId,
					sourceAccountId: account.id,
				},
				facts: emitted.facts,
			});
			markIngested(account);
		} catch (err) {
			log.error(
				{ err, userId: account.userId, providerId: account.providerId },
				"identity-engine: ingest failed",
			);
		}
	})();
}

/**
 * Disconnect-time tombstone. When a user unlinks an OAuth account, we have
 * an `account.id` (BetterAuth row id) but no live access token, so the
 * connector can't be queried. Instead we look up every providerStableId we
 * previously ingested under this `(connectorKey, sourceAccountId)` and call
 * `ingestFacts({ facts: [] })` for each, which the engine treats as
 * authoritative-empty and tombstones every prior fact + revokes derivations.
 *
 * Fire-and-forget. Errors are logged.
 */
export function scheduleIdentityTombstoneOnAccountDelete(
	account: AuthAccountSummary,
): void {
	void (async () => {
		try {
			recentIngest.delete(account.id);
			const providerKey = account.providerId.trim().toLowerCase();
			const sql = getDb();
			const rows = await sql<{ provider_stable_id: string }>`
        SELECT DISTINCT metadata->>'providerStableId' AS provider_stable_id
        FROM events
        WHERE semantic_type = 'identity_fact'
          AND connector_key = ${providerKey}
          AND metadata->>'sourceAccountId' = ${account.id}
          AND COALESCE(metadata->>'normalizedValue', '') <> ''
      `;
			if (rows.length === 0) return;

			const resolved = await resolveTenantMember(account.userId);
			if (!resolved) return;

			for (const row of rows) {
				if (!row.provider_stable_id) continue;
				await ingestFacts({
					tenantOrganizationId: resolved.tenantOrganizationId,
					memberEntityId: resolved.memberEntityId,
					userId: account.userId,
					accountIdentity: {
						connectorKey: providerKey,
						providerStableId: row.provider_stable_id,
						sourceAccountId: account.id,
					},
					facts: [],
				});
			}
		} catch (err) {
			log.error(
				{ err, userId: account.userId, providerId: account.providerId },
				"identity-engine: tombstone-on-delete failed",
			);
		}
	})();
}

/**
 * Identity engine.
 *
 * Reads connector-emitted facts and resolves them against catalog entities:
 * 1. Persist each fact as an event row (semantic_type='identity_fact'),
 * superseding the prior fact for the same (sourceAccountId, namespace).
 * 2. Look up entities in each public catalog whose identity-namespace
 * metadata field equals the fact's normalizedValue.
 * 3. Apply each catalog's relationship-type auto_create_when rules,
 * writing entity_relationships with provenance pointing back to the
 * source event. Skip when assurance < required, when match strategy
 * rejects ambiguity, or when the target relationship already exists.
 * 4. On supersede, revoke derivations whose source event is no longer
 * current (status='archived' on the relationship row + valid_to=now).
 *
 * Shadow mode (env IDENTITY_ENGINE_SHADOW=='true'): writes facts but
 * skips derivation/revocation writes. Used to validate behaviour against
 * real users before flipping derivations on.
 */

import { IDENTITY, normalizeEmailDomain } from "@lobu/connector-sdk";
import {
	type AssuranceLevel,
	type AutoCreateWhenRule,
	assuranceMeets,
	CLAIM_COLLISION_SEMANTIC_TYPE,
	type ConnectorFact,
	type DerivedFromProvenance,
	IDENTITY_FACT_SEMANTIC_TYPE,
} from "@lobu/connector-sdk/identity-types";
import { getDb } from "../db/client";
import { insertEvent } from "../utils/insert-event";
import logger from "../utils/logger";
import { validateTypeRule } from "../utils/relationship-validation";
import { TtlCache } from "../utils/ttl-cache";
import { connectorCapabilityRegistry } from "./capability-registry";
import { withAccountLock } from "./lock";
import { ruleHashFor } from "./rules";
import type { EngineOptions, IngestResult } from "./types";
import {
	IdentitySchemaError,
	validateClaimCollisionPayload,
	validateConnectorFact,
	validateDerivedRelationshipMetadata,
	validateFactEventMetadata,
	validateRelationshipTypeIdentityMetadata,
} from "./validate";

type Sql = ReturnType<typeof getDb>;

/**
 * Stable identity of the connector account driving this ingest. The durable
 * join key is `providerStableId` — the connector's immutable account
 * identifier — which survives email changes and reconnects that produce a
 * fresh BetterAuth account row. `sourceAccountId` is kept for provenance
 * only.
 */
interface AccountIdentity {
	/** Identifier of the connector implementation (events.connector_key). */
	connectorKey: string;
	/** Provider's immutable account id. The durable join key. */
	providerStableId: string;
	/** BetterAuth account row id; on new rows for the same provider account this differs. */
	sourceAccountId: string;
	/** Optional connection id for richer provenance. */
	connectionId?: number | null;
}

interface IngestParams {
	/** Tenant org these facts are scoped to (where the user's $member lives). */
	tenantOrganizationId: string;
	/** $member entity id in the tenant org for the authenticated user. */
	memberEntityId: number;
	/** Caller user id, used as `created_by` on event rows. */
	userId: string;
	/** Identity of the connector account producing this ingest. */
	accountIdentity: AccountIdentity;
	/**
	 * Set of facts the connector currently emits for this account. An empty
	 * array is interpreted AUTHORITATIVELY: every prior fact for this
	 * (connectorKey, providerStableId) is tombstoned and downstream
	 * derivations revoked. Callers that fail to fetch (network errors,
	 * provider unavailability) MUST NOT call ingestFacts — the engine has
	 * no way to distinguish fetch-failure from legitimate empty.
	 */
	facts: ConnectorFact[];
	/** Per-call shadow override; otherwise read from env. */
	options?: EngineOptions;
}

interface RuleRow {
	relationshipTypeId: number;
	relationshipTypeSlug: string;
	catalogOrganizationId: string;
	rules: AutoCreateWhenRule[];
	ruleVersion: number;
	ruleHash: string;
}

interface PriorFact {
	eventId: number;
	namespace: string;
	normalizedValue: string;
	providerStableId: string;
	assurance: AssuranceLevel;
}

const log = logger.child({ module: "identity-engine" });
const MAX_COLLISION_CANDIDATES = 16;

function isShadow(opts: EngineOptions | undefined): boolean {
	if (typeof opts?.shadow === "boolean") return opts.shadow;
	return process.env.IDENTITY_ENGINE_SHADOW === "true";
}

function originIdForFact(
	accountIdentity: AccountIdentity,
	fact: { namespace: string; normalizedValue: string },
): string {
	// Bind on (connectorKey, providerStableId, namespace, normalizedValue) so
	// a namespace with multiple values produces one fact per value, each with
	// its own supersede chain.
	return `identity_fact:${accountIdentity.connectorKey}:${accountIdentity.providerStableId}:${fact.namespace}:${fact.normalizedValue}`;
}

function priorKey(p: { namespace: string; normalizedValue: string }): string {
	// US (\x1f) delimiter banned by ConnectorFact field charset, so namespace
	// and normalizedValue can never produce the same join as another pair.
	return `${p.namespace}${p.normalizedValue}`;
}

/**
 * Engine-derived companion facts for a connector batch.
 *
 * `email_domain` is a pure function of an `email` fact (the part after `@`),
 * so the engine derives it centrally rather than asking every connector to
 * emit it — one authoritative rule, and any connector that produces `email`
 * gets domain-keyed matching (e.g. works_at → company.domain) for free. The
 * derived fact inherits the source email's assurance, providerStableId, and
 * sourceAccountId, so it supersedes/tombstones/revokes in lockstep with the
 * email: if the email goes away on refresh, so does the domain and any edge
 * it derived. Because it is engine-authored (not connector-declared) it is
 * exempt from the per-connector capability cap — its trust is exactly the
 * already-capped email fact's trust, never more.
 */
function deriveCompanionFacts(facts: ConnectorFact[]): ConnectorFact[] {
	// One companion per distinct domain, sourced from the STRONGEST-assurance
	// email at that domain — not first-input-order. If a person supplies both a
	// self_attested and an oauth_verified email at acme.com, the companion must
	// carry oauth_verified so the works_at rule (which requires it) still fires;
	// input order must not decide that.
	const byDomain = new Map<string, ConnectorFact>();
	for (const fact of facts) {
		if (fact.namespace !== IDENTITY.EMAIL) continue;
		const domain = normalizeEmailDomain(fact.normalizedValue);
		if (!domain) continue;
		const prior = byDomain.get(domain);
		if (prior && assuranceMeets(prior.assurance, fact.assurance)) continue;
		byDomain.set(domain, fact);
	}
	return Array.from(byDomain, ([domain, source]) => ({
		namespace: IDENTITY.EMAIL_DOMAIN,
		identifier: domain,
		normalizedValue: domain,
		assurance: source.assurance,
		providerStableId: source.providerStableId,
		sourceAccountId: source.sourceAccountId,
		validTo: source.validTo,
		notes: `derived from email ${source.normalizedValue}`,
	}));
}

function isSupersedeUniqueViolation(err: unknown): boolean {
	const e = err as {
		code?: unknown;
		constraint?: unknown;
		constraint_name?: unknown;
	};
	if (e?.code !== "23505") return false;
	return (
		e.constraint === "idx_events_superseded_by" ||
		e.constraint_name === "idx_events_superseded_by"
	);
}

function emptyResult(): IngestResult {
	return {
		factEventIds: [],
		supersededEventIds: [],
		derivedRelationshipIds: [],
		revokedRelationshipIds: [],
		collisionEventIds: [],
		skippedRules: [],
	};
}

/**
 * Public-catalog relationship types that declare auto_create_when rules.
 * Read once per ingest pass; small N (one row per relationship type that
 * opts into the engine).
 */
async function loadRules(sql: Sql): Promise<RuleRow[]> {
	const rows = await sql<{
		id: number;
		slug: string;
		organization_id: string;
		metadata: unknown;
	}>`
    SELECT rt.id, rt.slug, rt.organization_id, rt.metadata
    FROM entity_relationship_types rt
    JOIN organization o ON o.id = rt.organization_id
    WHERE rt.deleted_at IS NULL
      AND rt.status = 'active'
      AND o.visibility = 'public'
      AND rt.metadata ? 'autoCreateWhen'
  `;
	const out: RuleRow[] = [];
	for (const row of rows) {
		// Validate every metadata blob and reject rules whose stored ruleHash
		// disagrees with a fresh hash of their canonicalised rule set — that
		// means the YAML→DB seeder lost integrity and the engine must not act on
		// the rule until reseeded.
		try {
			validateRelationshipTypeIdentityMetadata(row.metadata);
		} catch (err) {
			log.warn(
				{ relationshipTypeId: row.id, err },
				"identity-engine: relationship type metadata failed schema validation; skipping rule",
			);
			continue;
		}
		const meta = row.metadata as {
			autoCreateWhen: AutoCreateWhenRule[];
			ruleVersion: number;
			ruleHash: string;
		};
		const expectedHash = ruleHashFor(meta.autoCreateWhen);
		if (expectedHash !== meta.ruleHash) {
			log.warn(
				{ relationshipTypeId: row.id, expectedHash, storedHash: meta.ruleHash },
				"identity-engine: relationship type ruleHash drift; skipping rule until reseeded",
			);
			continue;
		}
		out.push({
			relationshipTypeId: Number(row.id),
			relationshipTypeSlug: String(row.slug),
			catalogOrganizationId: String(row.organization_id),
			rules: meta.autoCreateWhen,
			ruleVersion: meta.ruleVersion,
			ruleHash: meta.ruleHash,
		});
	}
	return out;
}

async function loadPriorFacts(
	sql: Sql,
	accountIdentity: AccountIdentity,
): Promise<PriorFact[]> {
	// Diff on (connectorKey, providerStableId), not sourceAccountId, so facts
	// chain across BetterAuth account-row reissues on reconnect.
	//
	// Exclude tombstone rows (empty normalizedValue / identifier). Tombstones
	// are emitted when a namespace drops out of a refresh; if we counted them
	// as priors, every subsequent empty refresh would write a fresh tombstone
	// superseding the last one, chaining indefinitely.
	const rows = await sql<{
		id: number;
		metadata: {
			namespace?: string;
			normalizedValue?: string;
			assurance?: string;
		};
	}>`
    SELECT e.id, e.metadata
    FROM current_event_records e
    WHERE e.semantic_type = ${IDENTITY_FACT_SEMANTIC_TYPE}
      AND e.connector_key = ${accountIdentity.connectorKey}
      AND e.metadata->>'providerStableId' = ${accountIdentity.providerStableId}
      AND COALESCE(e.metadata->>'normalizedValue', '') <> ''
  `;
	return rows.map((r) => ({
		eventId: Number(r.id),
		namespace: String(r.metadata?.namespace ?? ""),
		normalizedValue: String(r.metadata?.normalizedValue ?? ""),
		providerStableId: accountIdentity.providerStableId,
		assurance: (r.metadata?.assurance ?? "self_attested") as AssuranceLevel,
	}));
}

interface MatchedEntity {
	entityId: number;
	organizationId: string;
}

/**
 * Only fields declared on an entity-type's metadata-schema with
 * `x-identity-namespace: true` are allowed as rule targets. Without this,
 * a malicious or careless rule could match on any JSONB field (e.g.
 * `internal_notes`, `system_secret`) and derive against wrong evidence.
 *
 * Cached per-org with a configurable TTL (default 60 s). Schema changes
 * (`x-identity-namespace` toggled on/off in YAML) propagate to all running
 * engines within this window; the seeder also bumps `ruleVersion` so
 * ruleHash drift invalidation kicks in. Override TTL via
 * `IDENTITY_FIELD_CACHE_TTL_MS`.
 */
const IDENTITY_FIELD_CACHE_TTL_MS = (() => {
	const raw = Number(process.env.IDENTITY_FIELD_CACHE_TTL_MS);
	return Number.isFinite(raw) && raw > 0 ? raw : 60_000;
})();

const identityFieldCache = new TtlCache<Set<string>>(
	IDENTITY_FIELD_CACHE_TTL_MS,
);

/**
 * Drop the in-memory cache. Tests use this to refresh after declaring new
 * identity fields; production callers can use it after a known schema
 * reseed if they don't want to wait out the TTL.
 */
export function clearIdentityFieldCache(): void {
	identityFieldCache.clear();
}

async function loadIdentityFields(
	sql: Sql,
	organizationId: string,
): Promise<Set<string>> {
	const cached = identityFieldCache.get(organizationId);
	if (cached) return cached;
	const rows = await sql<{ slug: string; metadata_schema: unknown }>`
    SELECT slug, metadata_schema
    FROM entity_types
    WHERE organization_id = ${organizationId}
      AND deleted_at IS NULL
      AND metadata_schema IS NOT NULL
  `;
	const allowed = new Set<string>();
	for (const row of rows) {
		const schema = row.metadata_schema as
			| {
					properties?: Record<
						string,
						{ "x-identity-namespace"?: boolean | Record<string, unknown> }
					>;
			  }
			| null
			| undefined;
		if (!schema || typeof schema !== "object" || !schema.properties) continue;
		for (const [field, def] of Object.entries(schema.properties)) {
			if (!def || typeof def !== "object") continue;
			const marker = def["x-identity-namespace"];
			if (marker === true || (marker && typeof marker === "object")) {
				allowed.add(field);
			}
		}
	}
	identityFieldCache.set(organizationId, allowed);
	return allowed;
}

async function findEntitiesByMetadataField(
	sql: Sql,
	catalogOrgId: string,
	field: string,
	normalizedValue: string,
): Promise<MatchedEntity[]> {
	const allowed = await loadIdentityFields(sql, catalogOrgId);
	if (!allowed.has(field)) {
		log.warn(
			{ catalogOrgId, field },
			"identity-engine: targetField is not declared x-identity-namespace; skipping match",
		);
		return [];
	}
	const rows = await sql<{ id: number; organization_id: string }>`
    SELECT e.id, e.organization_id
    FROM entities e
    WHERE e.organization_id = ${catalogOrgId}
      AND e.deleted_at IS NULL
      AND e.metadata->>${field} = ${normalizedValue}
  `;
	return rows.map((r) => ({
		entityId: Number(r.id),
		organizationId: r.organization_id,
	}));
}

async function findExistingRelationship(
	sql: Sql,
	fromEntityId: number,
	toEntityId: number,
	relationshipTypeId: number,
): Promise<number | null> {
	const rows = await sql<{ id: number }>`
    SELECT id FROM entity_relationships
    WHERE from_entity_id = ${fromEntityId}
      AND to_entity_id = ${toEntityId}
      AND relationship_type_id = ${relationshipTypeId}
      AND deleted_at IS NULL
    LIMIT 1
  `;
	return rows.length > 0 ? Number(rows[0].id) : null;
}

async function insertDerivation(
	sql: Sql,
	fromEntityId: number,
	toEntityId: number,
	relationshipTypeId: number,
	organizationId: string,
	userId: string,
	provenance: DerivedFromProvenance,
): Promise<number | null> {
	// Validating the wrapper recursively validates `provenance` too, so there
	// is no separate inner-only validator call.
	const metadata = { derivedFrom: provenance };
	validateDerivedRelationshipMetadata(metadata);
	// Defense in depth: loadRules already filters to active public-catalog
	// types, but a soft-deleted type rule, a YAML→DB mismatch, or a stale
	// rule version could otherwise let the engine derive a relationship that
	// the manual `manage_entity` API would reject.
	await validateTypeRule(relationshipTypeId, fromEntityId, toEntityId, sql);
	// Idempotent insert: ON CONFLICT covers the partial unique index when
	// two writers escape the in-process lock (e.g. multiple replicas).
	const rows = await sql<{ id: number }>`
    INSERT INTO entity_relationships (
      from_entity_id, to_entity_id, relationship_type_id, organization_id,
      metadata, created_by, updated_by
    ) VALUES (
      ${fromEntityId}, ${toEntityId}, ${relationshipTypeId}, ${organizationId},
      ${sql.json(metadata)}, ${userId}, ${userId}
    )
    ON CONFLICT DO NOTHING
    RETURNING id
  `;
	if (rows.length === 0) return null;
	return Number(rows[0].id);
}

async function revokeDerivationsForEvent(
	sql: Sql,
	eventId: number,
	userId: string,
): Promise<number[]> {
	const rows = await sql<{ id: number }>`
    UPDATE entity_relationships
    SET deleted_at = NOW(),
        updated_at = NOW(),
        updated_by = ${userId}
    WHERE deleted_at IS NULL
      AND metadata ? 'derivedFrom'
      AND metadata->'derivedFrom'->>'sourceEventId' = ${String(eventId)}
    RETURNING id
  `;
	return rows.map((r) => Number(r.id));
}

async function recordCollision(
	sql: Sql,
	tenantOrgId: string,
	factEventId: number,
	candidateMemberIds: number[],
	fact: ConnectorFact,
	accountIdentity: AccountIdentity,
	relationshipTypeId: number,
	userId: string,
): Promise<number | null> {
	const candidateEntityIds = candidateMemberIds.slice(
		0,
		MAX_COLLISION_CANDIDATES,
	);
	const payload = {
		kind: "identity_match" as const,
		namespace: fact.namespace,
		identifier: fact.identifier,
		normalizedValue: fact.normalizedValue,
		candidateEntityIds,
		candidateCount: candidateMemberIds.length,
		triggeringEventId: factEventId,
		relationshipTypeId,
	};
	validateClaimCollisionPayload(payload);
	// Key on (connectorKey, providerStableId), not the BetterAuth account row
	// id, which can be re-issued on reconnect — otherwise a reconnect produces
	// duplicate pending-approval events for the same underlying collision.
	const originId = `claim_collision:${accountIdentity.connectorKey}:${accountIdentity.providerStableId}:${fact.namespace}:${fact.normalizedValue}`;
	const existing = await sql<{ id: number }>`
    SELECT id
    FROM current_event_records
    WHERE organization_id = ${tenantOrgId}
      AND origin_id = ${originId}
      AND semantic_type = ${CLAIM_COLLISION_SEMANTIC_TYPE}
      AND interaction_type = 'approval'
      AND interaction_status = 'pending'
    ORDER BY created_at DESC, id DESC
    LIMIT 1
  `;
	if (existing.length > 0) return Number(existing[0].id);

	const ev = await insertEvent(
		{
			organizationId: tenantOrgId,
			entityIds: candidateEntityIds,
			originId,
			semanticType: CLAIM_COLLISION_SEMANTIC_TYPE,
			interactionType: "approval",
			interactionStatus: "pending",
			metadata: payload,
			title: `Identity match collision on ${fact.namespace}`,
			payloadType: "text",
			content: `Two or more candidate $member rows match this provider-verified ${fact.namespace}; manual resolution required.`,
			createdBy: userId,
		},
		{ sql },
	);
	return ev?.id ?? null;
}

/**
 * Main entry: ingest a fresh batch of facts for one connector account.
 * Idempotent — safe to call repeatedly with the same input; superseded
 * events stay in history.
 *
 * IMPORTANT: passing `facts: []` is AUTHORITATIVE — every prior fact for
 * `(connectorKey, providerStableId)` is tombstoned. Callers that fail to
 * fetch facts (network errors, provider unavailability) MUST NOT call
 * ingestFacts.
 */
export async function ingestFacts(params: IngestParams): Promise<IngestResult> {
	// Serialise concurrent passes for the same (connectorKey, providerStableId)
	// so simultaneous sign-ins / refreshes can't lost-update each other.
	return withAccountLock(
		params.accountIdentity.connectorKey,
		params.accountIdentity.providerStableId,
		() => ingestFactsLocked(params),
	);
}

async function ingestFactsLocked(params: IngestParams): Promise<IngestResult> {
	const {
		tenantOrganizationId,
		memberEntityId,
		userId,
		accountIdentity,
		facts: connectorFacts,
	} = params;
	const shadow = isShadow(params.options);

	// Expand the connector batch with engine-derived companion facts (e.g. an
	// `email_domain` fact for each `email`). These ride the same persist /
	// supersede / tombstone / derive machinery as connector facts, so absence
	// of the source email on a later refresh tombstones the domain too. Derived
	// facts are appended (never replace connector facts).
	//
	// `engineDerived` holds the exact fact OBJECTS the engine synthesized, so
	// the capability cap is skipped ONLY for those. A connector that itself
	// supplies an email_domain fact is NOT in this set and is still subject to
	// the cap — which no connector declares for email_domain, so a forged
	// companion is rejected. Keying the exemption on identity (not namespace)
	// is what closes that privilege hole.
	const companions = deriveCompanionFacts(connectorFacts);
	const engineDerived = new Set<ConnectorFact>(companions);
	const facts: ConnectorFact[] = [...connectorFacts, ...companions];

	// 1. Validate every fact up front. All-or-nothing — we do not partially
	// ingest, since a partial write could leave derivations dangling.
	const seenFactKeys = new Set<string>();
	for (const fact of facts) {
		try {
			validateConnectorFact(fact);
		} catch (err) {
			if (err instanceof IdentitySchemaError) {
				log.error(
					{
						err,
						namespace: fact?.namespace,
						connectorKey: accountIdentity.connectorKey,
					},
					"identity-engine: rejecting batch due to invalid fact",
				);
			}
			throw err;
		}
		// Identity coherence: facts in a batch must all belong to the same
		// provider account (matches AccountIdentity).
		if (fact.providerStableId !== accountIdentity.providerStableId) {
			throw new Error(
				`identity-engine: fact.providerStableId mismatches accountIdentity (got ${fact.providerStableId}, expected ${accountIdentity.providerStableId})`,
			);
		}
		if (fact.sourceAccountId !== accountIdentity.sourceAccountId) {
			throw new Error(
				`identity-engine: fact.sourceAccountId mismatches accountIdentity (got ${fact.sourceAccountId}, expected ${accountIdentity.sourceAccountId})`,
			);
		}
		const key = priorKey(fact);
		if (seenFactKeys.has(key)) {
			throw new Error(
				`identity-engine: duplicate fact in batch for namespace/value ${fact.namespace}/${fact.normalizedValue}`,
			);
		}
		seenFactKeys.add(key);
		// Engine-derived companion facts (e.g. email_domain) are authored by the
		// engine, not the connector, so no connector declares a capability for
		// them. They inherit the source fact's already-capped assurance, so the
		// cap is enforced upstream on the email fact — skip the connector cap for
		// THESE specific objects only. A connector-supplied fact of the same
		// namespace is not in the set and still faces the cap below.
		if (engineDerived.has(fact)) continue;
		// server-side capability cap: a connector may only emit
		// (namespace, assurance) pairs it declared in its capability. Anything
		// outside the declared cap is rejected before any side effect.
		const cap = connectorCapabilityRegistry.maxAssurance(
			accountIdentity.connectorKey,
			fact.namespace,
		);
		if (!cap) {
			throw new Error(
				`identity-engine: connector ${accountIdentity.connectorKey} has no registered capability for namespace ${fact.namespace}`,
			);
		}
		if (!assuranceMeets(cap, fact.assurance)) {
			throw new Error(
				`identity-engine: connector ${accountIdentity.connectorKey} cannot emit ${fact.assurance} for namespace ${fact.namespace} (capped at ${cap})`,
			);
		}
	}

	const result: IngestResult = emptyResult();

	// Wrap every write in a single transaction so a partial-batch failure
	// rolls back facts AND derivations together — never leaves derivations
	// pointing at events that no longer exist. A 23505 on
	// `idx_events_superseded_by` means another replica already wrote this
	// supersede; we treat the whole call as an idempotent no-op.
	try {
		return await getDb().begin(async (sql) => {
			// Index prior facts by (namespace, normalizedValue) so multi-value
			// namespaces are diffed independently.
			const priorFacts = await loadPriorFacts(sql, accountIdentity);
			const priorByKey = new Map<string, PriorFact>();
			for (const pf of priorFacts) {
				priorByKey.set(priorKey(pf), pf);
			}

			// 2. Persist each incoming fact, superseding the prior fact for the
			// matching (namespace, normalizedValue) tuple when one exists.
			const incomingByNamespaceValue = new Map<
				string,
				{ eventId: number; fact: ConnectorFact }
			>();
			for (const fact of facts) {
				const factMetadata = {
					namespace: fact.namespace,
					identifier: fact.identifier,
					normalizedValue: fact.normalizedValue,
					assurance: fact.assurance,
					providerStableId: fact.providerStableId,
					sourceAccountId: fact.sourceAccountId,
					validTo: fact.validTo,
					notes: fact.notes,
				};
				validateFactEventMetadata(factMetadata);

				const key = priorKey(fact);
				const supersedes = priorByKey.get(key)?.eventId ?? null;

				const inserted = await insertEvent(
					{
						organizationId: tenantOrganizationId,
						entityIds: [memberEntityId],
						originId: originIdForFact(accountIdentity, fact),
						semanticType: IDENTITY_FACT_SEMANTIC_TYPE,
						payloadType: "empty",
						metadata: factMetadata,
						connectorKey: accountIdentity.connectorKey,
						connectionId: accountIdentity.connectionId ?? null,
						supersedesEventId: supersedes,
						occurredAt: new Date(),
						createdBy: userId,
					},
					{ sql },
				);
				if (!inserted) {
					log.warn(
						{
							namespace: fact.namespace,
							providerStableId: accountIdentity.providerStableId,
						},
						"identity-engine: insertEvent returned null; skipping fact",
					);
					continue;
				}
				result.factEventIds.push(inserted.id);
				incomingByNamespaceValue.set(key, { eventId: inserted.id, fact });
				if (supersedes !== null) {
					result.supersededEventIds.push(supersedes);
				}
			}

			// 3. Diff prior vs current. Every prior (namespace, normalizedValue) the
			// connector no longer emits is tombstoned and its derivations revoked.
			// This is what makes empty-input authoritative and supports
			// multi-value namespaces correctly.
			for (const [key, pf] of priorByKey.entries()) {
				if (incomingByNamespaceValue.has(key)) continue;
				const tombstoneMeta = {
					namespace: pf.namespace,
					identifier: "",
					normalizedValue: "",
					assurance: "self_attested" as const,
					providerStableId: accountIdentity.providerStableId,
					sourceAccountId: accountIdentity.sourceAccountId,
					notes: "superseded by absence on connector refresh",
				};
				validateFactEventMetadata(tombstoneMeta);
				const tombstone = await insertEvent(
					{
						organizationId: tenantOrganizationId,
						entityIds: [memberEntityId],
						originId: `identity_fact_tombstone:${accountIdentity.connectorKey}:${accountIdentity.providerStableId}:${pf.namespace}:${pf.normalizedValue}`,
						semanticType: IDENTITY_FACT_SEMANTIC_TYPE,
						payloadType: "empty",
						metadata: tombstoneMeta,
						connectorKey: accountIdentity.connectorKey,
						connectionId: accountIdentity.connectionId ?? null,
						supersedesEventId: pf.eventId,
						occurredAt: new Date(),
						createdBy: userId,
					},
					{ sql },
				);
				if (tombstone) {
					result.factEventIds.push(tombstone.id);
					result.supersededEventIds.push(pf.eventId);
				}
			}

			if (shadow) {
				log.info(
					{
						factCount: facts.length,
						factEventIds: result.factEventIds.length,
						connectorKey: accountIdentity.connectorKey,
						providerStableId: accountIdentity.providerStableId,
					},
					"identity-engine: shadow mode — skipped derivation/revocation pass",
