interface BotDeliveryTarget {
	connectionId: string;
	platform: string;
	/** Platform-prefixed channel id ready for `chat.channel()`, e.g. "slack:C0123ABCD". */
	channelKey: string;
	/** Workspace/team id from the subscription — keys the owner-DM identity lookup. */
	teamId: string | null;
