/**
 * Google verified-facts emitter.
 *
 * Reads the Google `userinfo` payload for an authenticated account and
 * emits `ConnectorFact[]` with appropriate assurance. The platform layer
 * passes the result to `engine.ingestFacts`.
 *
 * Capability declaration is published statically so a future CI lint can
 * assert that this file never emits a namespace it didn't declare.
 */

import type {
	ConnectorFact,
	ConnectorIdentityCapability,
} from "@lobu/connector-sdk/identity-types";
import { normalizeEmail } from "@lobu/connector-sdk/identity-normalize";
import { fetchUserInfoWithRaw } from "../../connect/oauth-providers";
import logger from "../../utils/logger";
import {
	type ConnectorEmitParams,
	type ConnectorEmitResult,
	registerConnector,
} from "../capability-registry";

const log = logger.child({ module: "identity-connector-google" });

const googleIdentityCapability: ConnectorIdentityCapability = {
	connectorKey: "google",
	produces: [
		{
			namespace: "email",
			assurance: "oauth_verified",
			notes:
				"Google's verified primary email; survives provider-level account changes via providerStableId.",
		},
		{
			namespace: "hosted_domain",
			assurance: "oauth_verified",
			notes:
				"Google Workspace `hd` claim. Present only for Workspace accounts; absent for personal Gmail.",
		},
	],
};

/**
 * Fetch Google's userinfo payload and translate into ConnectorFacts.
 *
 * Returns `null` on fetch failure or when the response shape is too sparse
 * to assert anything authoritative — the engine would otherwise interpret
 * an empty `facts` array as a tombstone signal.
 */
async function getVerifiedFactsFromGoogle(
	params: ConnectorEmitParams,
): Promise<ConnectorEmitResult | null> {
	if (!params.accessToken) return null;

	let payload: Awaited<ReturnType<typeof fetchUserInfoWithRaw>>;
	try {
		payload = await fetchUserInfoWithRaw({
			provider: "google",
			accessToken: params.accessToken,
		});
	} catch (err) {
		log.warn(
			{ err, sourceAccountId: params.sourceAccountId },
			"google userinfo fetch failed",
		);
		return null;
	}

	if (!payload.raw) return null;
	const raw = payload.raw as {
		sub?: unknown;
		id?: unknown;
		email?: unknown;
		email_verified?: unknown;
		verified_email?: unknown;
		hd?: unknown;
	};

	const providerStableId = String(raw.sub ?? raw.id ?? "");
	if (!providerStableId) {
		log.warn(
			{ sourceAccountId: params.sourceAccountId },
			"google userinfo missing sub/id",
		);
		return null;
	}

	// Empty-input footgun: ingestFacts treats `facts: []` as authoritative and
	// tombstones every prior fact. If userinfo came back without ANY of the
	// claim shapes we read from (no `email` key AND no `hd` key), we can't
	// distinguish "user has nothing to share" from "scope was reduced or the
	// response is malformed." Bail with null so the prior facts survive.
	const hasReadableShape = "email" in raw || "hd" in raw;
	if (!hasReadableShape) {
		log.warn(
			{ sourceAccountId: params.sourceAccountId, providerStableId },
			"google userinfo missing both email and hd claims; refusing to assert empty state",
		);
		return null;
	}

	const facts: ConnectorFact[] = [];

	// Email — emitted only when explicitly verified by Google. Google's
	// OAuth2 v2 endpoint returns `verified_email`; OIDC userinfo returns
	// `email_verified`. Require either field to be boolean true.
	const emailVerified = raw.email_verified === true || raw.verified_email === true;
	if (typeof raw.email === "string" && emailVerified) {
		const normalized = normalizeEmail(raw.email);
		if (normalized) {
			facts.push({
				namespace: "email",
				identifier: raw.email,
				normalizedValue: normalized,
				assurance: "oauth_verified",
				providerStableId,
				sourceAccountId: params.sourceAccountId,
			});
		}
	}

	// Hosted domain — Google Workspace only. Absent for personal accounts.
	if (typeof raw.hd === "string" && raw.hd.length > 0) {
		const normalized = raw.hd.toLowerCase();
		facts.push({
			namespace: "hosted_domain",
			identifier: raw.hd,
			normalizedValue: normalized,
			assurance: "oauth_verified",
			providerStableId,
			sourceAccountId: params.sourceAccountId,
		});
	}

	return { providerStableId, facts };
}

// Self-registration. Importing this module is the only thing core code
// has to do to enable the Google connector — there's no `case 'google'`
// branch anywhere in the engine or auth-hook.
registerConnector({
	capability: googleIdentityCapability,
	emit: getVerifiedFactsFromGoogle,
});

/**
 * GitHub connector identity namespaces and normalization.
 *
 * Single source of truth for github_login / github_user_id / github_repo_* rules.
 * The connector, app-webhook actor resolution, repo ACL graph, and server
 * entity-link ingestion all import from here — not from connector-sdk.
 */

import type {
  AccessMember,
  AccessResource,
  AclSourceDef,
} from '@lobu/connector-sdk';
import type { ConnectorIdentityModule } from './connector-identity-module.js';

/** Connector-owned identity namespaces (not SDK-global). */
export const GITHUB_IDENTITY = {
  USER_ID: 'github_user_id',
  LOGIN: 'github_login',
  REPO_ID: 'github_repo_id',
  REPO_FULL_NAME: 'github_repo_full_name',
} as const;

export type GithubIdentityNamespace =
  (typeof GITHUB_IDENTITY)[keyof typeof GITHUB_IDENTITY];

export function normalizeGithubLogin(raw: string | null | undefined): string | null {
  if (typeof raw !== 'string') return null;
  const trimmed = raw.trim().toLowerCase();
  if (!trimmed) return null;
  if (!/^[a-z0-9](?:[a-z0-9]|-(?=[a-z0-9])){0,38}$/.test(trimmed)) return null;
  return trimmed;
}

function normalizeNumericId(raw: string | null | undefined): string | null {
  if (typeof raw !== 'string') return null;
  const trimmed = raw.trim();
  if (!/^\d+$/.test(trimmed)) return null;
  return trimmed.replace(/^0+(?=\d)/, '');
}

export function normalizeGithubRepoFullName(raw: string | null | undefined): string | null {
  if (typeof raw !== 'string') return null;
  const trimmed = raw.trim().toLowerCase();
  if (!trimmed) return null;
  const parts = trimmed.split('/');
  if (parts.length !== 2) return null;
  const [owner, repo] = parts;
  const githubName = /^[a-z0-9](?:[a-z0-9._-]{0,98}[a-z0-9])?$/;
  if (!githubName.test(owner) || !githubName.test(repo)) return null;
  return `${owner}/${repo}`;
}

/**
 * Normalize a GitHub identity namespace value. Returns `undefined` when the
 * namespace is not GitHub-owned (caller should fall back to generic hygiene).
 */
export function normalizeGithubIdentityValue(
  namespace: string,
  raw: string,
): string | null | undefined {
  switch (namespace) {
    case GITHUB_IDENTITY.LOGIN:
      return normalizeGithubLogin(raw);
    case GITHUB_IDENTITY.USER_ID:
    case GITHUB_IDENTITY.REPO_ID:
      return normalizeNumericId(raw);
    case GITHUB_IDENTITY.REPO_FULL_NAME:
      return normalizeGithubRepoFullName(raw);
    default:
      return undefined;
  }
}

/** Stable `github_user_id:ID` / `github_login:login` key used by poll + webhooks. */
export function githubUserIdentityKey(params: {
  userId?: string | number | null;
  login: string;
}): string {
  const normalizedLogin =
    normalizeGithubLogin(params.login) ?? params.login.toLowerCase();
  if (params.userId != null && String(params.userId).length > 0) {
    return `${GITHUB_IDENTITY.USER_ID}:${params.userId}`;
  }
  return `${GITHUB_IDENTITY.LOGIN}:${normalizedLogin}`;
}

/** Sanitize an identity key for inclusion in `origin_id` (connector + webhook). */
export function githubKeyForOriginId(key: string): string {
  return key.replace(/[^a-z0-9]+/gi, '_');
}

/** The GitHub connector's contribution to the server identity wiring. */
export const githubIdentityModule: ConnectorIdentityModule = {
  key: 'github',
  // github_login + github_user_id are recall-indexed
  // (idx_events_metadata_github_login / _github_user_id). The repo_* namespaces
  // are ACL resource keys, not event-recall namespaces.
  recallNamespaces: [GITHUB_IDENTITY.LOGIN, GITHUB_IDENTITY.USER_ID],
  normalize: normalizeGithubIdentityValue,
};

// ── ACL source ────────────────────────────────────────────────────────────
//
// A repo's read audience is its COLLABORATORS. Each repo becomes a `repo`
// entity keyed on its normalized `github_repo_full_name` (`owner/repo`) — the
// same key the connector stamps on ingested data — so the resource gate joins
// an event's repo to these member_of edges. Each collaborator resolves
// identity-first on github_user_id (+ github_login).

/** A repo collaborator as the GitHub collaborators API reports it. */
export interface GithubRepoCollaborator {
  login: string;
  id?: number;
}

/** A repository and the collaborators who may read it. */
export interface GithubRepoInput {
  /** `owner/repo`. */
  fullName: string;
  collaborators: GithubRepoCollaborator[];
}

/** The GitHub connector's ACL-source descriptor. */
export const githubAclSource: AclSourceDef = {
  key: 'github',
  resourceNamespace: GITHUB_IDENTITY.REPO_FULL_NAME,
  memberIdentities: [
    { namespace: GITHUB_IDENTITY.USER_ID, primary: true },
    { namespace: GITHUB_IDENTITY.LOGIN },
  ],
};

/**
 * Normalize GitHub repos + collaborators into engine resources. Each repo keyed
 * on its normalized `owner/repo`; each collaborator claims github_user_id (+
 * github_login). Repos with an unparseable full name, and collaborators with no
 * valid identity, are dropped.
 */
export function githubReposToResources(repos: GithubRepoInput[]): AccessResource[] {
  const resources: AccessResource[] = [];
  for (const repo of repos) {
    const key = normalizeGithubRepoFullName(repo.fullName);
    if (!key) continue;
    const members: AccessMember[] = [];
    for (const c of repo.collaborators) {
      const login = normalizeGithubLogin(c.login);
      const idValue = c.id != null ? normalizeNumericId(String(c.id)) : null;
      const identities: { namespace: string; value: string }[] = [];
      if (idValue) identities.push({ namespace: GITHUB_IDENTITY.USER_ID, value: idValue });
      if (login) identities.push({ namespace: GITHUB_IDENTITY.LOGIN, value: login });
      if (identities.length === 0) continue;
      members.push({ key: idValue ?? (login as string), name: c.login, identities });
    }
    resources.push({ key, name: repo.fullName, members });
  }
  return resources;
}

/**
 * The ACL source registry — the ONE place core code COLLECTS access-controlled
 * sources. Each descriptor is owned by its connector; this file only gathers
 * them so the generic gate and sync loop iterate without naming connectors.
 *
 * All sources materialize as entity type `$resource`. Identity namespaces
 * distinguish Slack channels, GitHub repos, etc.
 */

import type { AclSourceDef, ChannelReadIdentity } from '@lobu/connector-sdk';
import { githubAclSource } from '@lobu/connectors/github-identity';
import { slackAclSource, slackChannelReadIdentity } from '@lobu/connectors/slack-identity';

/** Every registered ACL source (contributed by its connector package). */
export const ACL_SOURCES: AclSourceDef[] = [slackAclSource, githubAclSource];

const ACL_SOURCE_BY_KEY = new Map<string, AclSourceDef>(ACL_SOURCES.map((s) => [s.key, s]));

/**
 * The ACL source descriptor for a connector key, or null when that connector
 * contributes no access-controlled resources.
 */
export function aclSourceFor(key: string): AclSourceDef | null {
  return ACL_SOURCE_BY_KEY.get(key) ?? null;
}

/**
 * Chat platforms whose per-channel read gate is enforced, keyed by `platform`.
 * GitHub is NOT here — its resource gate is repo-based, not chat-channel.
 */
export const CHANNEL_READ_IDENTITIES: ChannelReadIdentity[] = [slackChannelReadIdentity];

const CHANNEL_READ_IDENTITY_BY_PLATFORM = new Map<string, ChannelReadIdentity>(
  CHANNEL_READ_IDENTITIES.map((c) => [c.platform, c]),
);

/**
 * The read-gate identity model for a chat platform, or null when that platform
 * has no enforced channel gate.
 */
export function channelReadIdentityFor(platform: string): ChannelReadIdentity | null {
  return CHANNEL_READ_IDENTITY_BY_PLATFORM.get(platform) ?? null;
}

/**
 * Identity-engine SDK contracts.
 *
 * Connectors emit `ConnectorFact[]` for the authenticated subject; catalog
 * YAMLs declare `AutoCreateWhenRule[]` on relationship types; the engine
 * matches facts against rules and writes derivations.
 *
 * Schemas are TypeBox so they double as runtime validators at every write
 * boundary (seeder, engine, MCP tools). Validation is mandatory — the
 * collapsed model puts a lot in `metadata jsonb`, so without validation the
 * engine silently corrupts on malformed input.
 */

import { Type, type Static } from '@sinclair/typebox';

// =============================================================================
// Assurance levels
// =============================================================================

/**
 * How strongly the connector vouches for a fact. Rules require a minimum
 * assurance to fire. The order is total: `oauth_verified_admin_role` >
 * `oauth_verified` > `cookie_session` > `self_attested`.
 */
export const AssuranceLevel = Type.Union(
  [
    Type.Literal('oauth_verified_admin_role'),
    Type.Literal('oauth_verified'),
    Type.Literal('cookie_session'),
    Type.Literal('self_attested'),
  ],
  { $id: 'AssuranceLevel' }
);
export type AssuranceLevel = Static<typeof AssuranceLevel>;

const ASSURANCE_RANK: Record<AssuranceLevel, number> = {
  oauth_verified_admin_role: 4,
  oauth_verified: 3,
  cookie_session: 2,
  self_attested: 1,
};

export function assuranceMeets(actual: AssuranceLevel, required: AssuranceLevel): boolean {
  return ASSURANCE_RANK[actual] >= ASSURANCE_RANK[required];
}

// =============================================================================
// ConnectorFact — what a connector emits
// =============================================================================

export const ConnectorFact = Type.Object(
  {
    /** The attribute kind. Each connector declares which namespaces it produces. */
    namespace: Type.String({ minLength: 1, maxLength: 64 }),
    /** Raw value as the provider returned it. Audit-friendly. */
    identifier: Type.String({ minLength: 1, maxLength: 1024 }),
    /**
     * Canonicalised form used for index lookups. Connectors run normalize* on
     * the value before emitting; the engine re-normalises defensively.
     */
    normalizedValue: Type.String({ minLength: 1, maxLength: 1024 }),
    /** How the connector verified this fact. */
    assurance: AssuranceLevel,
    /**
     * Provider's immutable account identifier — the primary binding key
     * that survives email changes and account-row reissues.
     */
    providerStableId: Type.String({ minLength: 1, maxLength: 256 }),
    /**
     * Which connector account row produced this fact. Lets the engine diff
     * facts per session for revocation.
     */
    sourceAccountId: Type.String({ minLength: 1, maxLength: 256 }),
    /** ISO-8601 timestamp. Optional; required for high-assurance facts in production. */
    validTo: Type.Optional(Type.String({ minLength: 1, maxLength: 64 })),
    /**
     * Optional human-readable note about trust caveats this fact carries.
     * Surfaced in audit logs and admin UIs; never used by the engine.
     */
    notes: Type.Optional(Type.String({ maxLength: 512 })),
  },
  { $id: 'ConnectorFact', additionalProperties: false }
);
export type ConnectorFact = Static<typeof ConnectorFact>;

// =============================================================================
// ConnectorIdentityCapability — what a connector promises to emit
// =============================================================================

/**
 * Each connector exports a static capability declaration. CI lints that the
 * namespaces it actually emits at runtime are a subset of `produces`.
 */
export const ConnectorIdentityCapability = Type.Object(
  {
    connectorKey: Type.String({ minLength: 1, maxLength: 64 }),
    produces: Type.Array(
      Type.Object({
        namespace: Type.String({ minLength: 1, maxLength: 64 }),
        assurance: AssuranceLevel,
        notes: Type.Optional(Type.String({ maxLength: 512 })),
      }),
      { minItems: 0, maxItems: 32 }
    ),
  },
  { $id: 'ConnectorIdentityCapability', additionalProperties: false }
);
export type ConnectorIdentityCapability = Static<typeof ConnectorIdentityCapability>;

// =============================================================================
// AutoCreateWhenRule — declared on relationship-type YAMLs, compiled into
// entity_relationship_types.metadata.auto_create_when[]
// =============================================================================

/**
 * `unique_only` rejects ambiguity (writes a collision event for admin
 * resolution); `all_matches` fans out to every match and is only safe for
 * weak relationships. `first_match` is deliberately excluded — silently
 * picking a winner on collision would open adoption-takeover paths.
 */
export const MatchStrategy = Type.Union(
  [Type.Literal('unique_only'), Type.Literal('all_matches')],
  { $id: 'MatchStrategy' }
);
export type MatchStrategy = Static<typeof MatchStrategy>;

export const AutoCreateWhenRule = Type.Object(
  {
    /** The fact namespace this rule listens for. */
    sourceNamespace: Type.String({ minLength: 1, maxLength: 64 }),
    /**
     * The metadata field on the target entity-type whose normalized value
     * must equal the fact's normalizedValue.
     */
    targetField: Type.String({ minLength: 1, maxLength: 64 }),
    /**
     * Minimum assurance the fact must carry to fire this rule. The engine
     * enforces `assuranceMeets(fact.assurance, rule.assuranceRequired)`.
     */
    assuranceRequired: AssuranceLevel,
    matchStrategy: MatchStrategy,
    /**
     * Optional notes for review tooling — not consumed by the engine.
     */
    notes: Type.Optional(Type.String({ maxLength: 512 })),
  },
  { $id: 'AutoCreateWhenRule', additionalProperties: false }
);
export type AutoCreateWhenRule = Static<typeof AutoCreateWhenRule>;

/**
 * The shape stored on `entity_relationship_types.metadata`. Includes the
 * declared rules plus a version+hash so derivations can pin to the rule
 * version that fired them and reconciliation can detect drift.
 */
export const RelationshipTypeIdentityMetadata = Type.Object(
  {
    autoCreateWhen: Type.Array(AutoCreateWhenRule, { maxItems: 16 }),
    /** Monotonically increasing per relationship-type. Bumped by the seeder on every YAML change. */
    ruleVersion: Type.Integer({ minimum: 1 }),
    /** sha256 of the canonicalised auto_create_when array. Drift detection. */
    ruleHash: Type.String({ minLength: 64, maxLength: 64 }),
  },
  { $id: 'RelationshipTypeIdentityMetadata', additionalProperties: true }
);
export type RelationshipTypeIdentityMetadata = Static<typeof RelationshipTypeIdentityMetadata>;

// =============================================================================
// Fact event metadata — written into events.metadata when the engine
// persists a connector fact as `semantic_type='identity_fact'`
// =============================================================================

/**
 * Stored on `events.metadata` for `semantic_type='identity_fact'` rows.
 *
 * Tombstone facts (written when a connector refresh stops emitting a
 * namespace) carry empty `identifier`/`normalizedValue`/`providerStableId`,
 * which is why those fields allow empty strings here even though
 * `ConnectorFact` (the connector-side input) requires non-empty.
 */
export const FactEventMetadata = Type.Object(
  {
    namespace: Type.String({ minLength: 1, maxLength: 64 }),
    identifier: Type.String({ minLength: 0, maxLength: 1024 }),
    normalizedValue: Type.String({ minLength: 0, maxLength: 1024 }),
    assurance: AssuranceLevel,
    providerStableId: Type.String({ minLength: 0, maxLength: 256 }),
    sourceAccountId: Type.String({ minLength: 1, maxLength: 256 }),
    /** ISO-8601 timestamp string. Optional; required for high-assurance facts in production. */
    validTo: Type.Optional(Type.String({ minLength: 1, maxLength: 64 })),
    notes: Type.Optional(Type.String({ maxLength: 512 })),
  },
  { $id: 'FactEventMetadata', additionalProperties: false }
);
export type FactEventMetadata = Static<typeof FactEventMetadata>;

// =============================================================================
// DerivedFromProvenance — written into entity_relationships.metadata when
// the engine auto-creates a relationship
// =============================================================================

export const DerivedFromProvenance = Type.Object(
  {
    /** events.id of the fact that produced this derivation. */
    sourceEventId: Type.Integer({ minimum: 1 }),
    /** Which relationship-type rule fired (entity_relationship_types.id). */
    relationshipTypeId: Type.Integer({ minimum: 1 }),
    /** Snapshot of the rule version that fired. Drift signal for reconcile. */
    ruleVersion: Type.Integer({ minimum: 1 }),
    /** Hash matching ruleHash on the relationship-type at fire time. */
    ruleHash: Type.String({ minLength: 64, maxLength: 64 }),
    /** Echoed for fast assurance audits without joining back to the event. */
    factAssurance: AssuranceLevel,
    /** ISO-8601 timestamp. Echoes events.created_at; convenience for relationship-only audits. */
    derivedAt: Type.String({ minLength: 1, maxLength: 64 }),
  },
  { $id: 'DerivedFromProvenance', additionalProperties: false }
);
export type DerivedFromProvenance = Static<typeof DerivedFromProvenance>;

/**
 * The metadata blob stored on entity_relationships.metadata for derived
 * rows. Closed shape — extra keys are rejected so the engine can never
 * accidentally land junk alongside the provenance.
 */
export const DerivedRelationshipMetadata = Type.Object(
  {
    derivedFrom: DerivedFromProvenance,
  },
  { $id: 'DerivedRelationshipMetadata', additionalProperties: false }
);
export type DerivedRelationshipMetadata = Static<typeof DerivedRelationshipMetadata>;

// =============================================================================
// ClaimCollision — pending-approval event payload
// =============================================================================

/**
 * When a fact match would adopt a `$member` row that's already bound to a
 * different user (or vice versa), the engine writes a pending-approval event
 * with this shape. Resolution = a privileged user flips
 * `interaction_status='approved'` after merging entities, or 'rejected' to
 * dismiss without action.
 */
export const ClaimCollisionPayload = Type.Object(
  {
    kind: Type.Literal('identity_match'),
    namespace: Type.String({ minLength: 1, maxLength: 64 }),
    identifier: Type.String({ minLength: 1, maxLength: 1024 }),
    normalizedValue: Type.String({ minLength: 1, maxLength: 1024 }),
    /**
     * Catalog entity ids that all match this fact's normalized value.
     * Despite the historical name suggesting `$member`, these are general
     * catalog entities (founders, companies, etc.) — the resolver picks
     * which one the user intends to claim.
     */
    candidateEntityIds: Type.Array(Type.Integer({ minimum: 1 }), {
      minItems: 2,
      maxItems: 16,
    }),
    /** Total number of matching candidates; candidateEntityIds may be capped for UI payload size. */
    candidateCount: Type.Optional(Type.Integer({ minimum: 2 })),
    /**
     * Which fact (events.id) raised the collision. Lets the resolver replay
     * the binding once the human picks a winner.
     */
    triggeringEventId: Type.Integer({ minimum: 1 }),
    /** Rule that would have fired if the match were unambiguous. */
    relationshipTypeId: Type.Optional(Type.Integer({ minimum: 1 })),
  },
  { $id: 'ClaimCollisionPayload', additionalProperties: false }
);
export type ClaimCollisionPayload = Static<typeof ClaimCollisionPayload>;

// =============================================================================
// Constants — used by core code AND connector tests so the lint check has
// a single source of truth.
// =============================================================================

export const IDENTITY_FACT_SEMANTIC_TYPE = 'identity_fact' as const;
export const CLAIM_COLLISION_SEMANTIC_TYPE = 'claim_collision' as const;

