import { createLogger } from "@lobu/core";

const logger = createLogger("slack-web");

/**
 * Minimal Slack Web API surface used by the connected-apps onboarding flow:
 * open a DM channel with a user and post a message into it.
 *
 * Deliberately a dependency-free `fetch` wrapper — NOT `@slack/web-api`, NOT the
 * chat adapter. These are one-shot calls made with an INSTALLED workspace's bot
 * token, outside any live connection (the user clicks "Connect my DM" on the web
 * app), so spinning up the full adapter would be wasteful. Behind the
 * {@link SlackWebApi} interface so routes can inject a stub in tests.
 */
export interface SlackWebApi {
  /** `conversations.open` with a single user → the IM channel id (`D…`). */
  openDm(botToken: string, slackUserId: string): Promise<string>;
  /** `chat.postMessage` of a plain-text body. Throws on a Slack-level error. */
  postMessage(botToken: string, channel: string, text: string): Promise<void>;
  /**
   * `conversations.members` for one channel — the bare `U…` ids of every member,
   * following `response_metadata.next_cursor` to completion. Throws on a
   * Slack-level error (the ACL sync treats a throw as fail-closed). Used by the
   * authz channel-membership sync to materialize the read-ACL graph.
   */
  conversationMembers(botToken: string, channelId: string): Promise<string[]>;
  /**
   * `conversations.info` → the channel's human-readable name (e.g. `general`),
   * privacy flag, and the CONCRETE workspace team the channel lives in
   * (`context_team_id`). `name` is null when Slack omits it (e.g. a DM/MPIM or
   * an unreadable channel); callers fall back to the channel id. `contextTeamId`
   * is the real `T…` workspace id — on a Grid org-wide install this is the ONLY
   * place a binding can learn the channel's workspace (the install identity is
   * the enterprise `E…`, never a workspace), so the binding-team resolver reads
   * it here. Null when Slack omits it or the channel is unreadable.
   */
  conversationInfo(
    botToken: string,
    channelId: string
  ): Promise<{
    name: string | null;
    isPrivate: boolean;
    contextTeamId: string | null;
  }>;
  /**
   * `users.info` → the workspace-admin flags for one user. Used by the
   * marketplace-claim flow to verify the claiming user is a workspace admin or
   * owner before binding the pending install to their org. Throws on a
   * Slack-level error (the caller treats a throw as a failed claim).
   */
  usersInfo(
    botToken: string,
    userId: string
  ): Promise<{ isAdmin: boolean; isOwner: boolean }>;
  /**
   * `auth.revoke` — invalidate a bot token so an abandoned install can't leave a
   * live credential lying around. Best-effort by contract: an already-invalid or
   * unknown token yields a Slack-level error (`invalid_auth`, `token_revoked`)
   * which this throws on, and the caller treats any throw as "already gone" and
   * continues. Resolves to Slack's `revoked` flag on success. Used by the
   * expired-pending-install reaper.
   */
  revokeToken(botToken: string): Promise<boolean>;
  /**
   * `auth.test` — identify the workspace a bot token belongs to. Returns the
   * `T…` team id. Used by the ACL sync to self-heal a BYO connection that was
   * created without an OAuth install (so it never persisted a `teamId`): we
   * resolve the token's REAL team from Slack, verify it matches the channel
   * binding's team before graphing, and backfill it onto the connection row.
   * Throws on a Slack-level error (an invalid/revoked token yields `invalid_auth`).
   */
  authTest(botToken: string): Promise<{ teamId: string }>;
  /**
   * `oauth.v2.access` — exchange an OAuth `code` for the workspace bot token +
   * tenant/installer identity. Unlike the other methods this authenticates with
   * the app's client id/secret (not a bot token), so it lives outside
   * {@link slackPost}. Used by the marketplace / Slack-initiated install path,
   * which lands at the callback with a `code` but no Lobu-minted state — we need
   * the raw response (`authed_user`, `team`, `bot_user_id`) to park a pending
   * install and DM the installer to claim it.
   */
  exchangeOAuthCode(params: {
    clientId: string;
    clientSecret: string;
    code: string;
    redirectUri: string;
  }): Promise<{
    botToken: string;
    teamId: string;
    teamName: string | null;
    botUserId: string | null;
    authedUserId: string | null;
    isEnterpriseInstall: boolean;
    /**
     * The Grid enterprise id (`enterprise.id`) when the workspace belongs to a
     * Slack Grid/enterprise org, else null. NOTE: this is non-null even for a
     * SINGLE-workspace Grid install (where `is_enterprise_install` is false) —
     * the claim flow uses it to gate installer-identity claims, which are only
     * a valid authority proof on Grid (enterprise-global `U…` ids).
     */
    enterpriseId: string | null;
  }>;
}

async function slackPost(
  botToken: string,
  method: string,
  body: Record<string, unknown>
): Promise<Record<string, unknown>> {
  // Slack's read methods (conversations.members/list, users.info, …) accept ONLY
  // application/x-www-form-urlencoded — a JSON body yields `invalid_arguments`.
  // Form encoding is accepted by every Web API method (including chat.postMessage
  // / conversations.open used here), so encode uniformly.
  const form = new URLSearchParams();
  for (const [key, value] of Object.entries(body)) {
    if (value !== undefined && value !== null) form.set(key, String(value));
  }
  const res = await fetch(`https://slack.com/api/${method}`, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${botToken}`,
      "Content-Type": "application/x-www-form-urlencoded; charset=utf-8",
    },
    body: form.toString(),
  });
  const json = (await res.json()) as Record<string, unknown>;
  if (json.ok !== true) {
    throw new Error(`Slack ${method} failed: ${String(json.error ?? res.status)}`);
  }
  return json;
}

export function createSlackWebApi(): SlackWebApi {
  return {
    async openDm(botToken, slackUserId) {
      const json = await slackPost(botToken, "conversations.open", {
        users: slackUserId,
      });
      const channel = json.channel as { id?: string } | undefined;
      const channelId = channel?.id;
      if (typeof channelId !== "string" || !channelId) {
        throw new Error("Slack conversations.open returned no channel id");
      }
      return channelId;
    },
    async postMessage(botToken, channel, text) {
      try {
        await slackPost(botToken, "chat.postMessage", { channel, text });
      } catch (error) {
        // The welcome message is best-effort; the binding is the contract.
        logger.warn(
          { channel, error: String(error) },
          "Slack chat.postMessage failed"
        );
        throw error;
      }
    },
    async conversationMembers(botToken, channelId) {
      const members: string[] = [];
      let cursor: string | undefined;
      do {
        const json = await slackPost(botToken, "conversations.members", {
          channel: channelId,
          limit: 200,
          ...(cursor ? { cursor } : {}),
        });
        const page = Array.isArray(json.members)
          ? (json.members as unknown[]).filter(
              (m): m is string => typeof m === "string"
            )
          : [];
        members.push(...page);
        const meta = json.response_metadata as
          | { next_cursor?: string }
          | undefined;
        const next = meta?.next_cursor;
        cursor = next && next.length > 0 ? next : undefined;
      } while (cursor);
      return members;
    },
    async conversationInfo(botToken, channelId) {
      const json = await slackPost(botToken, "conversations.info", {
        channel: channelId,
      });
      const ch = json.channel as
        | { name?: string; is_private?: boolean; context_team_id?: string }
        | undefined;
      return {
        name: typeof ch?.name === "string" ? ch.name : null,
        isPrivate: ch?.is_private === true,
        contextTeamId:
          typeof ch?.context_team_id === "string" && ch.context_team_id
            ? ch.context_team_id
            : null,
      };
    },
    async usersInfo(botToken, userId) {
      const json = await slackPost(botToken, "users.info", { user: userId });
      const user = json.user as
        | { is_admin?: boolean; is_owner?: boolean }
        | undefined;
      return {
        isAdmin: user?.is_admin === true,
        isOwner: user?.is_owner === true,
      };
    },
    async revokeToken(botToken) {
      const json = await slackPost(botToken, "auth.revoke", {});
      return json.revoked === true;
    },
    async authTest(botToken) {
      const json = await slackPost(botToken, "auth.test", {});
      const teamId = json.team_id;
      if (typeof teamId !== "string" || !teamId) {
        throw new Error("Slack auth.test returned no team_id");
      }
      return { teamId };
    },
    async exchangeOAuthCode({ clientId, clientSecret, code, redirectUri }) {
      const form = new URLSearchParams({
        client_id: clientId,
        client_secret: clientSecret,
        code,
        redirect_uri: redirectUri,
      });
      const res = await fetch("https://slack.com/api/oauth.v2.access", {
        method: "POST",
        headers: {
          "Content-Type": "application/x-www-form-urlencoded; charset=utf-8",
        },
        body: form.toString(),
      });
      const json = (await res.json()) as Record<string, unknown>;
      if (json.ok !== true) {
        throw new Error(
          `Slack oauth.v2.access failed: ${String(json.error ?? res.status)}`
        );
      }
      const team = json.team as
        | { id?: string; name?: string }
        | null
        | undefined;
      const enterprise = json.enterprise as
        | { id?: string; name?: string }
        | null
        | undefined;
      const authedUser = json.authed_user as { id?: string } | undefined;
      const botToken = json.access_token;
      const isEnterpriseInstall = json.is_enterprise_install === true;
      const enterpriseId =
        typeof enterprise?.id === "string" ? enterprise.id : null;
      // For a Grid ORG-WIDE install the app is installed at the enterprise level,
      // so `oauth.v2.access` returns NO `team` — the enterprise id is the only
      // identity. Fall back to it as the routing/identity key (the pending row,
      // claim ref, and enterprise-fallback routing all key on this). A missing
      // team id is only fatal for a NON-enterprise install.
      const identityId =
        team?.id ?? (isEnterpriseInstall ? enterpriseId : null);
      if (typeof botToken !== "string" || !botToken) {
        throw new Error("Slack oauth.v2.access returned no access_token");
      }
      if (typeof identityId !== "string" || !identityId) {
        throw new Error("Slack oauth.v2.access returned no team id");
      }
      const subjectName =
        (typeof team?.name === "string" ? team.name : null) ??
        (isEnterpriseInstall && typeof enterprise?.name === "string"
          ? enterprise.name
          : null);
      return {
        botToken,
        teamId: identityId,
        teamName: subjectName,
        botUserId:
          typeof json.bot_user_id === "string" ? json.bot_user_id : null,
        authedUserId:
          typeof authedUser?.id === "string" ? authedUser.id : null,
        isEnterpriseInstall,
        enterpriseId,
      };
    },
  };
}

/**
 * Server-side connector capability + emitter registry.
 *
 * The engine accepts arbitrary `(namespace, assurance,
 * providerStableId)` tuples from each connector. Without a server-side
 * registry, a buggy or malicious connector could emit
 * `oauth_verified_admin_role` or a namespace it has no business producing
 * and trigger privileged rules. This registry caps each connector's
 * authority at its declared capability.
 *
 * The registry is the SINGLE place core code learns about connectors.
 * Engine, auth-hook, and admin tooling consult the registry; nothing in
 * core code names a specific connector. New connectors are added by
 * dropping a file in `connectors/` and registering at the bottom of that
 * file via `registerConnector(...)` — `connectors/index.ts` imports each
 * file for the side effect.
 */

import {
	assuranceMeets,
	type AssuranceLevel,
	type ConnectorFact,
	type ConnectorIdentityCapability,
} from "@lobu/connector-sdk/identity-types";

/**
 * Successful emit result. `facts` may be empty when the user's account is
 * legitimately producing no relevant attributes. The engine treats an
 * empty result authoritatively: prior facts get tombstoned.
 */
export interface ConnectorEmitResult {
	providerStableId: string;
	facts: ConnectorFact[];
}

export interface ConnectorEmitParams {
	accessToken: string;
	sourceAccountId: string;
}

/**
 * Connector emitter — fetches the provider's verified attributes for a
 * given access token and translates into ConnectorFacts. Returns `null`
 * On fetch failure (the caller MUST NOT call `ingestFacts` with a null
 * result, since that would tombstone everything on a transient outage).
 */
type ConnectorEmitter = (
	params: ConnectorEmitParams,
) => Promise<ConnectorEmitResult | null>;

interface ConnectorRegistration {
	capability: ConnectorIdentityCapability;
	emit: ConnectorEmitter;
}

interface RegistryEntry {
	registration: ConnectorRegistration;
	byNamespace: Map<string, AssuranceLevel>;
}

class ConnectorCapabilityRegistry {
	private readonly entries = new Map<string, RegistryEntry>();

	/**
	 * Register a connector. Throws on duplicate `connectorKey` to surface stray
	 * imports / mis-wired test bootstraps; tests that legitimately need to swap
	 * a registration use `replace: true`.
	 */
	register(
		registration: ConnectorRegistration,
		options?: { replace?: boolean },
	): void {
		const key = registration.capability.connectorKey;
		if (this.entries.has(key) && !options?.replace) {
			throw new Error(
				`connector capability already registered for "${key}"; pass { replace: true } to override`,
			);
		}
		const byNamespace = new Map<string, AssuranceLevel>();
		for (const produces of registration.capability.produces) {
			const prior = byNamespace.get(produces.namespace);
			if (!prior || assuranceMeets(produces.assurance, prior)) {
				byNamespace.set(produces.namespace, produces.assurance);
			}
		}
		this.entries.set(key, { registration, byNamespace });
	}

	/** Number of registered connectors — used by startup assertions. */
	size(): number {
		return this.entries.size;
	}

	get(connectorKey: string): RegistryEntry | undefined {
		return this.entries.get(connectorKey);
	}

	emitter(connectorKey: string): ConnectorEmitter | undefined {
		return this.entries.get(connectorKey)?.registration.emit;
	}

	/**
	 * Return the registered max-assurance for `(connectorKey, namespace)`,
	 * or `null` when the connector is not registered or doesn't declare the
	 * namespace at all. Engine rejects facts in either case — silence is not
	 * trust.
	 */
	maxAssurance(connectorKey: string, namespace: string): AssuranceLevel | null {
		const entry = this.entries.get(connectorKey);
		if (!entry) return null;
		return entry.byNamespace.get(namespace) ?? null;
	}

	/** Snapshot of every registered connector. */
	list(): ConnectorIdentityCapability[] {
		return Array.from(this.entries.values()).map(
			(entry) => entry.registration.capability,
		);
	}
}

export const connectorCapabilityRegistry = new ConnectorCapabilityRegistry();

/** Convenience for connector modules: `registerConnector({ capability, emit })`. */
export function registerConnector(registration: ConnectorRegistration): void {
	connectorCapabilityRegistry.register(registration);
}

/**
 * Per-account ingest mutex for the identity engine.
 *
 * Pi P0.3 — two simultaneous sign-ins for the same provider account can
 * load the same prior facts and race the inserts. Originally implemented
 * with `pg_advisory_lock`, but `getDb()` returns the singleton postgres.js
 * pool: advisory locks are session-scoped, so the lock and the queries
 * inside it would have run on different physical connections — the lock
 * was a no-op (caught by the QA agent).
 *
 * Single-process (the only deployment shape today): an in-memory promise
 * chain keyed on `(connectorKey, providerStableId)` serialises ingest calls
 * for the same account.
 *
 * Multi-process safety net (future replica deployments): the DB enforces
 * the actual invariants — `idx_events_superseded_by` is unique on
 * `supersedes_event_id`, and `idx_entity_relationships_live_triple` is
 * unique on `(from, to, relationship_type) WHERE deleted_at IS NULL`. A
 * cross-replica race that escapes this in-process mutex will hit one of
 * those indexes and fail loudly rather than silently corrupting. When the
 * service grows past one replica per provider account, swap this for a
 * dedicated-connection `pg_advisory_lock` (or Redis lock) — the call site
 * stays the same.
 */

const inflight = new Map<string, Promise<unknown>>();

function lockKey(connectorKey: string, providerStableId: string): string {
  return `${connectorKey}�${providerStableId}`;
}

/**
 * Run `fn` with exclusive access for the given account identity. Concurrent
 * calls for the same `(connectorKey, providerStableId)` queue up; calls for
 * different accounts run independently in parallel. Re-throws after
 * releasing the lock if `fn` fails.
 */
export async function withAccountLock<T>(
  connectorKey: string,
  providerStableId: string,
  fn: () => Promise<T>
): Promise<T> {
  const key = lockKey(connectorKey, providerStableId);
  const prior = inflight.get(key);
  let release: () => void;
  const next = new Promise<void>((resolve) => {
    release = resolve;
  });
  inflight.set(key, next);
  if (prior) {
    // Wait for the previous holder to finish (success or failure).
    try {
      await prior;
    } catch {
      // Predecessor's failure is not our concern; we still get our turn.
    }
  }
  try {
    return await fn();
  } finally {
    // Release this slot. If a successor is already queued they're chained
    // on `next`; if not, clean up the map entry to bound memory.
    if (inflight.get(key) === next) {
      inflight.delete(key);
    }
    release!();
  }
}

import { createHash } from "node:crypto";
import type { AutoCreateWhenRule } from "@lobu/connector-sdk";
import { validateRelationshipTypeIdentityMetadata } from "./validate";

function canonicaliseRules(rules: AutoCreateWhenRule[]): string {
	return JSON.stringify(
		rules
			.map((r) => ({
				sourceNamespace: r.sourceNamespace,
				targetField: r.targetField,
				assuranceRequired: r.assuranceRequired,
				matchStrategy: r.matchStrategy,
			}))
			.sort((a, b) =>
				a.sourceNamespace === b.sourceNamespace
					? a.targetField.localeCompare(b.targetField)
					: a.sourceNamespace.localeCompare(b.sourceNamespace),
			),
	);
}

export function ruleHashFor(rules: AutoCreateWhenRule[]): string {
	return createHash("sha256").update(canonicaliseRules(rules)).digest("hex");
}

/**
 * Build the metadata blob that lands on `entity_relationship_types.metadata`
 * for a public-catalog rule. Validates the result so seeders / test fixtures
 * never persist a malformed shape — bad rules are caught at write, not at
 * the next ingest pass.
 */
export function compileRulesMetadata(
	rules: AutoCreateWhenRule[],
	ruleVersion: number,
): {
	autoCreateWhen: AutoCreateWhenRule[];
	ruleVersion: number;
	ruleHash: string;
} {
	const metadata = {
		autoCreateWhen: rules,
		ruleVersion,
		ruleHash: ruleHashFor(rules),
	};
	validateRelationshipTypeIdentityMetadata(metadata);
	return metadata;
}

/**
 * Runtime validation for the identity-engine schemas (T1).
 *
 * Every write boundary into the engine — connector ingest, rule-compile,
 * derivation insert, collision event — runs the relevant TypeBox schema and
 * throws on malformed input. The collapsed model puts a lot in `metadata
 * jsonb`, so without this discipline the engine silently corrupts.
 */

import {
	TypeCompiler,
	type ValueErrorIterator,
} from "@sinclair/typebox/compiler";
import type { TSchema, Static } from "@sinclair/typebox";
import {
	ClaimCollisionPayload,
	ConnectorFact,
	DerivedRelationshipMetadata,
	FactEventMetadata,
	RelationshipTypeIdentityMetadata,
} from "@lobu/connector-sdk/identity-types";

const compiledFact = TypeCompiler.Compile(ConnectorFact);
const compiledFactEventMetadata = TypeCompiler.Compile(FactEventMetadata);
const compiledRelTypeMeta = TypeCompiler.Compile(
	RelationshipTypeIdentityMetadata,
);
const compiledDerivedRelMeta = TypeCompiler.Compile(
	DerivedRelationshipMetadata,
);
const compiledClaimCollision = TypeCompiler.Compile(ClaimCollisionPayload);

export class IdentitySchemaError extends Error {
	constructor(
		public readonly schemaName: string,
		public readonly errors: Array<{
			path: string;
			message: string;
			value: unknown;
		}>,
	) {
		const summary = errors
			.slice(0, 3)
			.map((e) => `${e.path || "<root>"}: ${e.message}`)
			.join("; ");
		const more = errors.length > 3 ? ` (+${errors.length - 3} more)` : "";
		super(`${schemaName} validation failed: ${summary}${more}`);
		this.name = "IdentitySchemaError";
	}
}

function collectErrors(iter: ValueErrorIterator): Array<{
	path: string;
	message: string;
	value: unknown;
}> {
	const errs: Array<{ path: string; message: string; value: unknown }> = [];
	for (const err of iter) {
		errs.push({ path: err.path, message: err.message, value: err.value });
		if (errs.length >= 16) break;
	}
	return errs;
}

function ensure<T extends TSchema>(
	schemaName: string,
	compiler: ReturnType<typeof TypeCompiler.Compile<T>>,
	value: unknown,
): asserts value is Static<T> {
	if (compiler.Check(value)) return;
	throw new IdentitySchemaError(
		schemaName,
		collectErrors(compiler.Errors(value)),
	);
}

export function validateConnectorFact(
	value: unknown,
): asserts value is Static<typeof ConnectorFact> {
	ensure("ConnectorFact", compiledFact, value);
}

export function validateFactEventMetadata(
	value: unknown,
): asserts value is Static<typeof FactEventMetadata> {
	ensure("FactEventMetadata", compiledFactEventMetadata, value);
}

export function validateRelationshipTypeIdentityMetadata(
	value: unknown,
): asserts value is Static<typeof RelationshipTypeIdentityMetadata> {
	ensure("RelationshipTypeIdentityMetadata", compiledRelTypeMeta, value);
}

export function validateDerivedRelationshipMetadata(
	value: unknown,
): asserts value is Static<typeof DerivedRelationshipMetadata> {
	ensure("DerivedRelationshipMetadata", compiledDerivedRelMeta, value);
}

export function validateClaimCollisionPayload(
	value: unknown,
): asserts value is Static<typeof ClaimCollisionPayload> {
	ensure("ClaimCollisionPayload", compiledClaimCollision, value);
}

/**
 * ACL-source contract — the shared shape between a connector and the generic
 * access-graph engine.
 *
 * A connector that gates read access on membership (Slack channels, GitHub
 * repos, …) reduces to: RESOURCES × AUDIENCE of MEMBERS. The connector owns
 * normalization into that shape; the server materializes entities, identities,
 * and `member_of` edges. Core never names a connector.
 *
 * All ACL resources are entity type `$resource`. Sources differ only by
 * resource identity namespace and member identity namespaces.
 */

/**
 * Sole platform entity-type slug for ACL-gated units.
 * `$` prefix → system (hide rail, never prune, user-create blocked).
 */
export const ACL_RESOURCE_TYPE_SLUG = '$resource' as const;

/** Columns used when ensuring the platform `$resource` entity type. */
export const ACL_RESOURCE_TYPE = {
  slug: ACL_RESOURCE_TYPE_SLUG,
  name: 'Resource',
  description:
    'ACL-gated access unit (Slack channel, GitHub repository, …). Graph anchor only — empty metadata schema.',
  icon: 'shield',
} as const;

/**
 * A claim that identifies a member, e.g. `{namespace:'slack_user_id', primary:true}`.
 * The engine collapses a member onto any existing entity carrying ANY of their
 * identities; `primary` ones additionally govern creation.
 */
export interface AccessIdentitySpec {
  namespace: string;
  primary?: boolean;
}

/** One member of a resource's audience. */
export interface AccessMember {
  /** Stable dedupe key (e.g. `T…:U…` for Slack, numeric id for GitHub). */
  key: string;
  /** Display name for an auto-created `person`. Falls back to `key`. */
  name?: string;
  /** This member's identity claims (namespaces in `memberIdentities`). */
